// ---------------------------------------------------------------------------
// PUBLIC referral intake — the first no-login surface in this app.
//   GET  /api/referral/:slug  → the minimum the form needs to render:
//                               business name + partner first name + serviços.
//   POST /api/referral/:slug  → creates a gm_leads row via gmInsertLead with
//                               parceiro_id set from the slug lookup (never a
//                               text match), origem 'Parceiro', estágio
//                               'Novo Lead'.
// Treated as hostile input by default: strict slug shape, server-side
// validation/truncation of every field, per-slug and per-IP rate limits in
// D1 (gm_referral_hits), a honeypot field and a minimum fill time. Responses
// never carry lead ids, other partners, or any client data beyond the
// business display name.
// ---------------------------------------------------------------------------

var GM_MONTH_NAMES_PT = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];

// Local date/time in the app's timezone (America/New_York), matching what
// the portal's own gmNowLocalIso() would produce on a phone in Florida.
function gmNyNowParts() {
    var fmt = new Intl.DateTimeFormat("en-CA", {
        timeZone: APEX_TIMEZONE, year: "numeric", month: "2-digit",
        day: "2-digit", hour: "2-digit", minute: "2-digit", hour12: false
    });
    var parts = {};
    fmt.formatToParts(new Date()).forEach(function(p) { parts[p.type] = p.value; });
    // en-CA can render midnight as "24" — normalize to 00
    if (parts.hour === "24") { parts.hour = "00"; }
    return parts;
}

function gmReferralSlugValid(slug) {
    return /^[a-z2-7]{10,40}$/.test(slug || "");
}

async function gmPartnerBySlug(env, slug) {
    if (!gmReferralSlugValid(slug)) { return null; }
    return env.DB.prepare(
        "SELECT p.id, p.client_id, p.name, c.name AS business_name, " +
        "c.language, c.referral_bg_color, c.referral_text_color, c.logo_url " +
        "FROM gm_partners p JOIN clients c ON c.id = p.client_id " +
        "WHERE p.referral_slug = ?"
    ).bind(slug).first();
}

// Apex's own palette — the literal values referral.html already hardcodes.
// Used as the fallback when a client has set no branding of their own.
var REFERRAL_DEFAULT_BG   = "#1a1a1d";   // --header
var REFERRAL_DEFAULT_TEXT = "#C9A43A";   // --gold

function referralHexOrNull(v) {
    return /^#[0-9a-fA-F]{6}$/.test(String(v || "")) ? String(v) : null;
}

async function handleGetReferralInfo(slug, request, env) {
    try {
        var partner = await gmPartnerBySlug(env, slug);
        if (!partner) { return jsonErr("Not found", 404); }
        var config = await gmGetConfig(env, partner.client_id);
        // Only what the public form needs — no ids, no other partners, no
        // financials. Partner first name only (it's their own link).
        //
        // Branding is resolved to concrete values HERE rather than sent as
        // nulls for the page to interpret: referral.html is deliberately
        // dependency-free, and the fallback rule (Apex black/gold) belongs in
        // one place. A stored value that is not a valid 6-digit hex is treated
        // as unset — the page can never be handed a broken color.
        var logoUrl = null;
        if (partner.logo_url) {
            // Served through the EXISTING logo-image route; no raw R2 key is
            // ever exposed to a public page.
            logoUrl = new URL(request.url).origin + "/api/clients/" + partner.client_id + "/logo-image";
        }
        return jsonOk({
            business_name: partner.business_name,
            partner_name: (partner.name || "").split(/\s+/)[0],
            servicos: config.servicos,
            language: partner.language === "en" ? "en" : "pt",
            referral_bg_color:   referralHexOrNull(partner.referral_bg_color)   || REFERRAL_DEFAULT_BG,
            referral_text_color: referralHexOrNull(partner.referral_text_color) || REFERRAL_DEFAULT_TEXT,
            has_logo: !!logoUrl,
            logo_url: logoUrl
        });
    } catch (e) {
        return jsonErr("Error loading referral form", 500);
    }
}

// ===========================================================================
// APEX'S OWN REFERRAL PARTNERS  (apex_partners)
//
// DATA TIER NOTE — the distinction this whole file keeps having to repeat:
//   gm_partners   = a CLIENT's referral partners (LIRA's suppliers). One tier
//                   below Apex, scoped by client_id, client-accessible.
//   apex_partners = APEX's own referral partners: who sends COACHING CLIENTS
//                   to Apex. This section. No client_id exists on the table,
//                   so there is no client scope to grant — every authenticated
//                   route here is isAdminRole-only, full stop, and a
//                   client-role token can never reach any of it.
//
// A referred lead lands in the APEX-INTERNAL pipeline (clients.status='lead',
// the Task-1 ladder), never in any client's gm_leads. Attribution is by record
// through clients.referred_by_partner_id, never by matching a typed name.
// ===========================================================================

// Apex's own partner statuses — same three-rung ladder as gm_partners, so the
// two screens read identically. Deliberately a separate constant: the client
// tier's list is configurable per client, Apex's own is fixed.
var APEX_PARTNER_STATUSES = ["Prospectando", "Ativo", "Inativo"];

function apexPartnerFields(body, partial) {
    var out = {};
    function has(k) { return Object.prototype.hasOwnProperty.call(body, k); }
    if (!partial || has("name")) {
        var name = gmStr(body.name, 200);
        if (!name) { return { error: "Nome do parceiro é obrigatório" }; }
        out.name = name;
    }
    if (has("status")) {
        if (APEX_PARTNER_STATUSES.indexOf(body.status) === -1) { return { error: "Status inválido" }; }
        out.status = body.status;
    }
    // tipo is FREE TEXT here, unlike gm_partners.tipo which validates against
    // the client's configurable partner_types list. Apex has no such list to
    // configure and only two people use this screen.
    if (has("tipo")) { out.tipo = body.tipo === null ? null : gmStr(body.tipo, 100); }
    if (has("contato")) { out.contato = body.contato === null ? null : gmStr(body.contato, 200); }
    if (has("ultima_interacao")) { out.ultima_interacao = body.ultima_interacao === null ? null : gmStr(body.ultima_interacao, 40); }
    if (has("proxima_acao")) { out.proxima_acao = body.proxima_acao === null ? null : gmStr(body.proxima_acao, 500); }
    return { fields: out };
}

// ---------------------------------------------------------------------------
// Route: GET /api/apex-partners — admin only
//
// clientes_indicados / clientes_convertidos are COMPUTED here and never
// stored, the same rule gm_partners follows for leads_indicados: a stored
// counter drifts the moment a lead is deleted, converted or re-attributed.
// ---------------------------------------------------------------------------

async function handleGetApexPartners(request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!isAdminRole(user)) { return jsonErr("Forbidden", 403); }

        // Backfill, mirroring handleGetGmPartners: partners created before a
        // slug existed get one on first read, so every card can show its link.
        var missing = await env.DB.prepare(
            "SELECT id FROM apex_partners WHERE referral_slug IS NULL"
        ).all();
        var missingRows = missing.results || [];
        for (var mi = 0; mi < missingRows.length; mi++) {
            await env.DB.prepare("UPDATE apex_partners SET referral_slug = ? WHERE id = ?")
                .bind(gmReferralSlug(), missingRows[mi].id).run();
        }

        var rows = await env.DB.prepare(
            "SELECT p.*, " +
            "(SELECT COUNT(*) FROM clients c WHERE c.referred_by_partner_id = p.id) AS clientes_indicados, " +
            // "Converted" means the referred lead actually became a paying
            // client — status='active'. A lead still in the pipeline counts as
            // referred but not yet converted.
            "(SELECT COUNT(*) FROM clients c WHERE c.referred_by_partner_id = p.id AND c.status = 'active') AS clientes_convertidos " +
            "FROM apex_partners p ORDER BY p.name COLLATE NOCASE"
        ).all();

        return jsonOk({ partners: rows.results || [], statuses: APEX_PARTNER_STATUSES });
    } catch (e) {
        return jsonErr("Error fetching Apex partners: " + e.message, 500);
    }
}

async function handlePostApexPartner(request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!isAdminRole(user)) { return jsonErr("Forbidden", 403); }

        var body = {};
        try { body = await request.json(); } catch (e2) { body = {}; }
        var parsed = apexPartnerFields(body, false);
        if (parsed.error) { return jsonErr(parsed.error, 400); }
        var f = parsed.fields;

        var rowId = crypto.randomUUID();
        await env.DB.prepare(
            "INSERT INTO apex_partners (id, name, tipo, contato, status, ultima_interacao, proxima_acao, referral_slug) " +
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
        ).bind(rowId, f.name,
            f.tipo !== undefined ? f.tipo : null,
            f.contato !== undefined ? f.contato : null,
            f.status !== undefined ? f.status : "Prospectando",
            f.ultima_interacao !== undefined ? f.ultima_interacao : null,
            f.proxima_acao !== undefined ? f.proxima_acao : null,
            gmReferralSlug()).run();

        var row = await env.DB.prepare("SELECT * FROM apex_partners WHERE id = ?").bind(rowId).first();
        return jsonOk({ created: true, partner: row });
    } catch (e) {
        return jsonErr("Error creating Apex partner: " + e.message, 500);
    }
}

async function handlePutApexPartner(rowId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!isAdminRole(user)) { return jsonErr("Forbidden", 403); }

        var existing = await env.DB.prepare("SELECT id FROM apex_partners WHERE id = ?").bind(rowId).first();
        if (!existing) { return jsonErr("Partner not found", 404); }

        var body = {};
        try { body = await request.json(); } catch (e2) { body = {}; }
        var parsed = apexPartnerFields(body, true);
        if (parsed.error) { return jsonErr(parsed.error, 400); }
        var f = parsed.fields;

        var sets = [], binds = [];
        Object.keys(f).forEach(function(k) { sets.push(k + " = ?"); binds.push(f[k]); });
        if (!sets.length) { return jsonErr("Nothing to update", 400); }
        sets.push("updated_at = datetime('now')");
        binds.push(rowId);

        await gmRunUpdate(env, "UPDATE apex_partners SET " + sets.join(", ") + " WHERE id = ?", binds);

        var row = await env.DB.prepare("SELECT * FROM apex_partners WHERE id = ?").bind(rowId).first();
        return jsonOk({ saved: true, partner: row });
    } catch (e) {
        return jsonErr("Error updating Apex partner: " + e.message, 500);
    }
}

async function handleDeleteApexPartner(rowId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!isAdminRole(user)) { return jsonErr("Forbidden", 403); }

        var existing = await env.DB.prepare("SELECT id FROM apex_partners WHERE id = ?").bind(rowId).first();
        if (!existing) { return jsonErr("Partner not found", 404); }

        // Leads this partner referred are NOT deleted — they are real people in
        // Apex's pipeline. Their attribution is cleared instead, so the lead
        // survives with no partner rather than pointing at a missing row.
        await env.DB.prepare(
            "UPDATE clients SET referred_by_partner_id = NULL WHERE referred_by_partner_id = ?"
        ).bind(rowId).run();
        await env.DB.prepare("DELETE FROM apex_partners WHERE id = ?").bind(rowId).run();

        return jsonOk({ deleted: true });
    } catch (e) {
        return jsonErr("Error deleting Apex partner: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// PUBLIC: GET/POST /api/apex-referral/:slug — Apex's own referral landing.
//
// Deliberately mirrors the gm_partners public form, with three differences
// that follow from this being Apex's own tool rather than a client's:
//   * PT only — no language field. Rafa and Alice are both Brazilian and this
//     page represents Apex itself, not a client with American customers.
//   * Apex's own black/gold always. No per-partner color customization.
//   * A submission creates a row in the APEX-INTERNAL pipeline
//     (clients.status='lead', lead_stage='Lead') — never a gm_leads row.
// ---------------------------------------------------------------------------

async function apexPartnerBySlug(env, slug) {
    if (!gmReferralSlugValid(slug)) { return null; }
    return env.DB.prepare(
        "SELECT id, name FROM apex_partners WHERE referral_slug = ?"
    ).bind(slug).first();
}

async function handleGetApexReferralInfo(slug, request, env) {
    try {
        var partner = await apexPartnerBySlug(env, slug);
        if (!partner) { return jsonErr("Not found", 404); }
        // First name only — it is the partner's own link, and nothing else
        // about Apex's partner roster is exposed publicly.
        return jsonOk({ partner_name: (partner.name || "").split(/\s+/)[0] });
    } catch (e) {
        return jsonErr("Error loading referral form", 500);
    }
}

async function handlePostApexReferralLead(slug, request, env) {
    try {
        var partner = await apexPartnerBySlug(env, slug);
        if (!partner) { return jsonErr("Not found", 404); }

        var ip = request.headers.get("CF-Connecting-IP") || "";

        // Same rate-limit shape as the gm referral form, against its OWN
        // ledger table: 10/hour per link, 20/hour per IP, counted BEFORE the
        // body is read so invalid payloads cannot bypass the counter.
        await env.DB.prepare(
            "DELETE FROM apex_referral_hits WHERE created_at < datetime('now', '-2 days')"
        ).run();
        var slugHits = await env.DB.prepare(
            "SELECT COUNT(*) AS c FROM apex_referral_hits WHERE slug = ? AND created_at > datetime('now', '-1 hour')"
        ).bind(slug).first();
        var ipHits = ip ? await env.DB.prepare(
            "SELECT COUNT(*) AS c FROM apex_referral_hits WHERE ip = ? AND created_at > datetime('now', '-1 hour')"
        ).bind(ip).first() : { c: 0 };
        if ((slugHits && slugHits.c >= 10) || (ipHits && ipHits.c >= 20)) {
            return jsonErr("Muitas tentativas. Tente novamente mais tarde.", 429);
        }
        await env.DB.prepare(
            "INSERT INTO apex_referral_hits (id, slug, ip) VALUES (?, ?, ?)"
        ).bind(crypto.randomUUID(), slug, ip || null).run();

        var body = {};
        try { body = await request.json(); } catch (e2) { body = {}; }

        // Honeypot + impossibly-fast submit get a FAKE success, so bots do not
        // learn to adapt. Identical to the gm form's treatment.
        var elapsed = gmNum(body.elapsed_ms);
        if (gmStr(body.website, 200) !== null || (elapsed !== null && elapsed >= 0 && elapsed < 3000)) {
            return jsonOk({ created: true });
        }

        var nome = gmStr(body.nome, 200);
        if (!nome) { return jsonErr("Nome é obrigatório", 400); }
        var telefone = gmStr(body.telefone, 60);
        if (telefone && !/^[0-9+()\-.\s]{7,60}$/.test(telefone)) {
            return jsonErr("Telefone inválido", 400);
        }
        var email = gmStr(body.email, 200);
        if (email && !/^[^@\s]+@[^@\s.]+\.[^@\s]+$/.test(email)) {
            return jsonErr("Email inválido", 400);
        }

        // Lands in the APEX-INTERNAL pipeline at the first rung, with
        // stage_changed_at stamped so Task 1's "days in this stage" starts
        // counting from arrival rather than reading as unknown.
        var leadId = crypto.randomUUID();
        await env.DB.prepare(
            // source_type is stamped 'partner' here rather than inferred later
            // from the non-null partner id: the Overview card and the future
            // attribution metrics read source_type, and a lead that arrived
            // through a partner's own link is the least ambiguous partner
            // referral there is. referred_by_partner_id stays authoritative for
            // WHICH partner — the name is never copied into source_detail.
            "INSERT INTO clients (id, name, status, lead_stage, stage_changed_at, phone, email, referred_by_partner_id, source_type) " +
            "VALUES (?, ?, 'lead', 'Lead', datetime('now'), ?, ?, ?, 'partner')"
        ).bind(leadId, nome, telefone, email, partner.id).run();

        // Deliberately no id and no data in the public response.
        return jsonOk({ created: true });
    } catch (e) {
        return jsonErr("Error submitting referral", 500);
    }
}

async function handlePostReferralLead(slug, request, env) {
    try {
        var partner = await gmPartnerBySlug(env, slug);
        if (!partner) { return jsonErr("Not found", 404); }

        var ip = request.headers.get("CF-Connecting-IP") || "";

        // Rate limit BEFORE reading the body: 10/hour per link, 20/hour per
        // IP. Every attempt is a hit, valid or not, so hammering invalid
        // payloads cannot bypass the counter. Old rows pruned opportunistically.
        await env.DB.prepare(
            "DELETE FROM gm_referral_hits WHERE created_at < datetime('now', '-2 days')"
        ).run();
        var slugHits = await env.DB.prepare(
            "SELECT COUNT(*) AS c FROM gm_referral_hits WHERE slug = ? AND created_at > datetime('now', '-1 hour')"
        ).bind(slug).first();
        var ipHits = ip ? await env.DB.prepare(
            "SELECT COUNT(*) AS c FROM gm_referral_hits WHERE ip = ? AND created_at > datetime('now', '-1 hour')"
        ).bind(ip).first() : { c: 0 };
        if ((slugHits && slugHits.c >= 10) || (ipHits && ipHits.c >= 20)) {
            return jsonErr("Muitas tentativas. Tente novamente mais tarde. / Too many attempts. Try again later.", 429);
        }
        await env.DB.prepare(
            "INSERT INTO gm_referral_hits (id, slug, ip) VALUES (?, ?, ?)"
        ).bind(crypto.randomUUID(), slug, ip || null).run();

        var body = {};
        try { body = await request.json(); } catch (e2) { body = {}; }

        // Honeypot: real users never see the 'website' field. Bots that fill
        // it get a fake success so they don't adapt. Same for an impossibly
        // fast submit (3 fields in under 3 seconds).
        var elapsed = gmNum(body.elapsed_ms);
        if (gmStr(body.website, 200) !== null || (elapsed !== null && elapsed >= 0 && elapsed < 3000)) {
            return jsonOk({ created: true });
        }

        var nome = gmStr(body.nome, 200);
        if (!nome) { return jsonErr("Nome é obrigatório / Name is required", 400); }
        var telefone = gmStr(body.telefone, 60);
        if (telefone && !/^[0-9+()\-.\s]{7,60}$/.test(telefone)) {
            return jsonErr("Telefone inválido / Invalid phone", 400);
        }
        var config = await gmGetConfig(env, partner.client_id);
        // servico may hold SEVERAL services as one comma-separated string
        // ("Pavers, Lighting") — validate each against the client's catalog,
        // drop unknowns, store the surviving list re-joined.
        var servicoRaw = gmStr(body.servico, 400);
        var servico = null;
        if (servicoRaw) {
            var servicoList = [];
            servicoRaw.split(",").forEach(function(part) {
                var t = part.trim();
                if (t && config.servicos.indexOf(t) !== -1 && servicoList.indexOf(t) === -1) {
                    servicoList.push(t);
                }
            });
            servico = servicoList.length ? servicoList.join(", ") : null;
        }

        var now = gmNyNowParts();
        var mesLead = GM_MONTH_NAMES_PT[Number(now.month) - 1];
        if (config.cycle_months.indexOf(mesLead) === -1) { mesLead = null; }

        // Same insert path as the authenticated quick-add — parceiro_id from
        // the slug's own partner row, by record.
        await gmInsertLead(env, partner.client_id, {
            cliente: nome,
            telefone: telefone,
            servico: servico,
            origem: "Parceiro",
            parceiro_id: partner.id,
            estagio: "novo_lead",
            data_lead: now.year + "-" + now.month + "-" + now.day + "T" + now.hour + ":" + now.minute,
            mes_lead: mesLead,
            observacao: "Recebido pelo link de indicação do parceiro."
        });   // no actor: the public referral form has no authenticated user
        // Deliberately no lead id / no data in the public response.
        return jsonOk({ created: true });
    } catch (e) {
        return jsonErr("Error submitting referral", 500);
    }
}

// ---------------------------------------------------------------------------
// Route: GET/POST /api/clients/:id/gm/finance, PUT /gm/finance/:rowId
// tipo is DERIVED from categoria via gm_config — a request body's tipo is
// never read. Monthly summary: ENTRADAS | SAÍDAS | RESULTADO | MARGEM.
// ---------------------------------------------------------------------------

async function handleGetGmFinance(id, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        var rows = await env.DB.prepare(
            "SELECT f.*, j.obra AS obra_name FROM gm_finance f " +
            "LEFT JOIN gm_jobs j ON j.id = f.obra_id " +
            "WHERE f.client_id = ? ORDER BY COALESCE(f.data, f.created_at) DESC"
        ).bind(id).all();
        var sums = await env.DB.prepare(
            "SELECT mes, " +
            "SUM(CASE WHEN tipo = 'Entrada' THEN valor ELSE 0 END) AS entradas, " +
            "SUM(CASE WHEN tipo = 'Saída' THEN valor ELSE 0 END) AS saidas " +
            "FROM gm_finance WHERE client_id = ? GROUP BY mes"
        ).bind(id).all();
        var monthly = [];
        (sums.results || []).forEach(function(m) {
            var entradas = m.entradas || 0;
            var saidas = m.saidas || 0;
            var resultado = entradas - saidas;
            monthly.push({
                mes: m.mes,
                entradas: entradas,
                saidas: saidas,
                resultado: resultado,
                margem_pct: entradas > 0 ? Math.round((resultado / entradas) * 1000) / 10 : null
            });
        });
        return jsonOk({ entries: rows.results || [], monthly: monthly });
    } catch (e) {
        return jsonErr("Error fetching finance entries: " + e.message, 500);
    }
}

async function gmFinanceFields(body, config, partial, env, clientId) {
    var out = {};
    function has(k) { return Object.prototype.hasOwnProperty.call(body, k); }
    if (!partial || has("descricao")) {
        var descricao = gmStr(body.descricao, 500);
        if (!descricao) { return { error: "DESCRIÇÃO é obrigatória" }; }
        out.descricao = descricao;
    }
    if (!partial || has("categoria")) {
        var categoria = gmStr(body.categoria, 80);
        var tipo = categoria ? gmFinanceTipo(config, categoria) : null;
        if (!tipo) { return { error: "Categoria inválida" }; }
        out.categoria = categoria;
        out.tipo = tipo;   // derived — body.tipo is never read
    }
    if (!partial || has("valor")) {
        var valor = gmNum(body.valor);
        if (valor === null || valor < 0) { return { error: "VALOR deve ser um número" }; }
        out.valor = valor;
    }
    if (has("obra_id")) {
        if (body.obra_id === null || body.obra_id === "") {
            out.obra_id = null;
        } else {
            var job = await gmOwnedRow(env, "gm_jobs", String(body.obra_id), clientId);
            if (!job) { return { error: "Obra não encontrada" }; }
            out.obra_id = job.id;
        }
    }
    if (has("mes")) { out.mes = body.mes === null ? null : gmStr(body.mes, 40); }
    if (has("data")) { out.data = body.data === null ? null : gmStr(body.data, 40); }
    if (has("obs")) { out.obs = body.obs === null ? null : gmStr(body.obs, 2000); }
    return { fields: out };
}

async function handlePostGmFinance(id, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        var body = {};
        try { body = await request.json(); } catch (e2) { body = {}; }
        var config = await gmGetConfig(env, id);
        var parsed = await gmFinanceFields(body, config, false, env, id);
        if (parsed.error) { return jsonErr(parsed.error, 400); }
        var f = parsed.fields;
        var rowId = crypto.randomUUID();
        await env.DB.prepare(
            "INSERT INTO gm_finance (id, client_id, mes, data, descricao, categoria, tipo, valor, obra_id, obs) " +
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        ).bind(rowId, id,
            f.mes !== undefined ? f.mes : null,
            f.data !== undefined ? f.data : null,
            f.descricao, f.categoria, f.tipo, f.valor,
            f.obra_id !== undefined ? f.obra_id : null,
            f.obs !== undefined ? f.obs : null).run();
        var row = await gmOwnedRow(env, "gm_finance", rowId, id);
        return jsonOk({ created: true, entry: row });
    } catch (e) {
        return jsonErr("Error creating finance entry: " + e.message, 500);
    }
}

async function handlePutGmFinance(id, rowId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        var existing = await gmOwnedRow(env, "gm_finance", rowId, id);
        if (!existing) { return jsonErr("Entry not found", 404); }
        var body = {};
        try { body = await request.json(); } catch (e2) { body = {}; }
        var config = await gmGetConfig(env, id);
        var parsed = await gmFinanceFields(body, config, true, env, id);
        if (parsed.error) { return jsonErr(parsed.error, 400); }
        var f = parsed.fields;
        var sets = [], binds = [];
        Object.keys(f).forEach(function(k) { sets.push(k + " = ?"); binds.push(f[k]); });
        if (!sets.length) { return jsonErr("Nothing to update", 400); }
        sets.push("updated_at = datetime('now')");
        binds.push(rowId); binds.push(id);
        await gmRunUpdate(env, "UPDATE gm_finance SET " + sets.join(", ") + " WHERE id = ? AND client_id = ?", binds);
        var row = await gmOwnedRow(env, "gm_finance", rowId, id);
        return jsonOk({ saved: true, entry: row });
    } catch (e) {
        return jsonErr("Error updating finance entry: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Route: GET/POST /api/clients/:id/gm/jobs, PUT /gm/jobs/:rowId
// CUSTO TOTAL / LUCRO / MARGEM % / ALVO? / NO PRAZO? computed at read time.
// ---------------------------------------------------------------------------

function gmJobComputed(row, targetMargin) {
    var custoTotal = (row.material || 0) + (row.mao_de_obra || 0) + (row.outros || 0);
    var lucro = row.valor === null || row.valor === undefined ? null : row.valor - custoTotal;
    var margemPct = (row.valor && row.valor > 0 && lucro !== null)
        ? Math.round((lucro / row.valor) * 1000) / 10 : null;
    var noPrazo = null;
    if (row.entrega_real && row.prazo_previsto) { noPrazo = row.entrega_real <= row.prazo_previsto; }
    return {
        custo_total: custoTotal,
        lucro: lucro,
        margem_pct: margemPct,
        // ALVO? — warn when margin is below the client's configured minimum.
        // "No proposal goes out below this number."
        //
        // THREE-STATE, not boolean. null means the question cannot be answered:
        // either the job has no margin yet, or the client has no target set.
        // The targetMargin check is load-bearing — `margemPct >= null` coerces
        // to `margemPct >= 0` in JS, which would silently mark EVERY job as
        // on-target the moment a client's floor is unset. A job at 24.9%
        // against an unset target is not "on target", it is unmeasured, and
        // the UI must say so rather than show a green check.
        alvo_ok: (margemPct === null || targetMargin === null || targetMargin === undefined)
                     ? null : margemPct >= targetMargin,
        no_prazo: noPrazo
    };
}

// ---------------------------------------------------------------------------
// Route: GET /api/clients/:id/gm/seller-diagnostics  — ADMIN ONLY
//
// Per-salesperson performance for ONE client, for seller-diagnostics.html.
//
// WHY THIS IS RAFA-SIDE AND NOT CLIENT-SIDE — record this, do not change it.
//
// This data identifies a specific employee BY NAME and characterizes their
// performance. In a consultant's hands it is coaching material. Handed to an
// owner with no framing it could get someone fired over a metric nobody
// explained to them, and it depends heavily on how much sales training the
// owner themselves has. So it stays with Rafa, who decides who sees it and
// discusses it with the owner rather than springing it on them.
//
// It may move client-side later, per client, at Rafa's discretion. That is a
// future decision, not a TODO.
//
// The gate is isAdminRole HERE, server-side. It is deliberately NOT added to
// clientRequestAllowed or sellerRequestAllowed — a client or seller session
// gets a 403 from the role gate before this handler is ever reached, and an
// unlinked page is not a protected page. Two 403 bugs shipped in this feature
// because a route was never added to the allowlist while handler checks
// passed; this is the same failure mode in reverse, and the fix is that this
// route appears in NEITHER allowlist.
//
// SMALL SAMPLES ARE SUPPRESSED, NOT ROUNDED. Every metric carries its own
// sample size, and any ratio computed on fewer than GM_DIAG_MIN_SAMPLE leads
// returns null so the page renders "not enough data yet" instead of a number.
// A 100% closing ratio off one deal, shown to a consultant who then acts on
// it, is worse than showing nothing — and that is the state of every client in
// the system today. Follows the existing cross-client-average precedent, which
// suppresses below 3 contributing clients and shows sample size on the number.
// ---------------------------------------------------------------------------

// Ratios below this many underlying leads are not reported as numbers.
var GM_DIAG_MIN_SAMPLE = 5;

// Live stages for "days in stage" — closed and lost leads have stopped ageing
// and would otherwise drag every average toward however long the history is.
var GM_DIAG_LIVE_STAGES = GM_LIVE_STAGES;

// A ratio that refuses to answer on thin data. Returns null (render as "not
// enough data yet") rather than a misleading number.
function gmDiagRatio(numerator, denominator, sample) {
    if (!denominator || denominator <= 0) { return null; }
    if ((sample === null || sample === undefined ? denominator : sample) < GM_DIAG_MIN_SAMPLE) { return null; }
    return Math.round((numerator / denominator) * 1000) / 10;
}

function gmDiagMedian(values) {
    if (!values || !values.length) { return null; }
    var v = values.slice().sort(function(a, b) { return a - b; });
    var mid = Math.floor(v.length / 2);
    var m = v.length % 2 ? v[mid] : (v[mid - 1] + v[mid]) / 2;
    return Math.round(m * 10) / 10;
}

// Whole days between two SQLite datetimes, or null if either is missing.
function gmDiagDaysBetween(a, b) {
    if (!a || !b) { return null; }
    var ms = Date.parse(String(b).replace(" ", "T") + "Z") - Date.parse(String(a).replace(" ", "T") + "Z");
    if (!isFinite(ms)) { return null; }
    return ms / 86400000;
}

function gmDiagMinutesBetween(a, b) {
    var d = gmDiagDaysBetween(a, b);
    return d === null ? null : d * 1440;
}

async function handleGetGmSellerDiagnostics(id, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        // Admin roles only — developer, alice, rafa. A client or seller session
        // never reaches this line (the role gate rejects it first), but the
        // check is here too so the handler is safe on its own terms.
        if (!isAdminRole(user)) { return jsonErr("Forbidden", 403); }

        var client = await env.DB.prepare("SELECT id, name FROM clients WHERE id = ?").bind(id).first();
        if (!client) { return jsonErr("Client not found", 404); }

        // Optional ?seller=<name> narrows every metric to one salesperson.
        // Absent means "across all sellers for this client".
        var sellerFilter = gmStr(new URL(request.url).searchParams.get("seller"), 80);

        // The roster: everyone with a seat, plus anyone who owns leads or has
        // logged contacts. A seller who lost their seat still has history worth
        // reading, and a vendedor name typed on a lead never had a seat at all.
        var seatRows = await env.DB.prepare(
            "SELECT seller_name FROM client_logins WHERE client_id = ? AND role = 'seller' AND seller_name IS NOT NULL"
        ).bind(id).all();
        var leadSellerRows = await env.DB.prepare(
            "SELECT DISTINCT vendedor AS seller_name FROM gm_leads " +
            "WHERE client_id = ? AND vendedor IS NOT NULL AND vendedor <> ''"
        ).bind(id).all();
        var contactSellerRows = await env.DB.prepare(
            "SELECT DISTINCT logged_by AS seller_name FROM gm_lead_contacts " +
            "WHERE client_id = ? AND logged_by IS NOT NULL AND logged_by <> ''"
        ).bind(id).all();

        var seatNames = {};
        (seatRows.results || []).forEach(function(r) { if (r.seller_name) { seatNames[r.seller_name] = true; } });
        var roster = {};
        Object.keys(seatNames).forEach(function(n) { roster[n] = true; });
        (leadSellerRows.results || []).forEach(function(r) { if (r.seller_name) { roster[r.seller_name] = true; } });
        (contactSellerRows.results || []).forEach(function(r) { if (r.seller_name) { roster[r.seller_name] = true; } });
        var sellers = Object.keys(roster).sort();

        // Every lead for the client, with its contact log attached. The data
        // volumes here are small by construction (this whole feature exists
        // because they are), so the aggregation is done in JS where the
        // definitions stay readable rather than across ten SQL variants.
        var leadBinds = sellerFilter ? [id, sellerFilter] : [id];
        var leadRows = await env.DB.prepare(
            // `cliente` is the lead's own name and comes back aliased as `nome`
            // so the biggest-win/biggest-loss tiles can name the actual deal.
            "SELECT id, cliente AS nome, vendedor, estagio, valor, origem, data_lead, data_contato, data_estimate, " +
            "stage_changed_at, created_at FROM gm_leads WHERE client_id = ?" +
            (sellerFilter ? " AND vendedor = ?" : "")
        ).bind(...leadBinds).all();
        var leads = leadRows.results || [];

        var contactRows = await env.DB.prepare(
            "SELECT c.id, c.lead_id, c.method, c.result, c.notes, c.objection, c.logged_by, c.logged_at, " +
            "l.vendedor, l.estagio FROM gm_lead_contacts c " +
            "JOIN gm_leads l ON l.id = c.lead_id WHERE c.client_id = ?" +
            (sellerFilter ? " AND COALESCE(c.logged_by, l.vendedor) = ?" : "")
        ).bind(...leadBinds).all();
        var contacts = contactRows.results || [];

        // ── Metric 1 — speed to first contact (data_contato − data_lead) ────
        // LIRA's own declared SLA, not one Apex imposed: "1º contato < 5 min".
        var firstContactMins = [];
        var slaContactBreaches = 0;
        leads.forEach(function(l) {
            var m = gmDiagMinutesBetween(l.data_lead, l.data_contato);
            if (m === null || m < 0) { return; }
            firstContactMins.push(m);
            if (m > 5) { slaContactBreaches++; }
        });

        // ── Metric 2 — speed to estimate (data_estimate − data_contato) ─────
        // The client's other declared SLA: "estimate < 24h".
        var estimateHrs = [];
        var slaEstimateBreaches = 0;
        leads.forEach(function(l) {
            var d = gmDiagDaysBetween(l.data_contato, l.data_estimate);
            if (d === null || d < 0) { return; }
            estimateHrs.push(d * 24);
            if (d > 1) { slaEstimateBreaches++; }
        });

        // ── Metric 3 — contact ratio (attempts ÷ conversations reached) ─────
        var attempts = contacts.length;
        var answered = contacts.filter(function(c) { return c.result === "Answered"; }).length;

        // ── Metric 4 — outcome after conversation ───────────────────────────
        // Of the leads actually REACHED, how many moved a stage after that
        // conversation versus stalled where they were.
        var reachedLeadIds = {};
        contacts.forEach(function(c) {
            if (c.result === "Answered") {
                if (!reachedLeadIds[c.lead_id] || c.logged_at < reachedLeadIds[c.lead_id]) {
                    reachedLeadIds[c.lead_id] = c.logged_at;
                }
            }
        });
        var advancedAfter = 0, stalledAfter = 0;
        leads.forEach(function(l) {
            var firstAnswered = reachedLeadIds[l.id];
            if (!firstAnswered) { return; }
            // stage_changed_at after the conversation = the conversation moved it.
            if (l.stage_changed_at && l.stage_changed_at > firstAnswered) { advancedAfter++; }
            else { stalledAfter++; }
        });

        // ── Metric 5 — days in stage, live leads only ───────────────────────
        var stageDays = {};
        leads.forEach(function(l) {
            if (GM_DIAG_LIVE_STAGES.indexOf(l.estagio) < 0) { return; }
            var since = l.stage_changed_at || l.created_at;
            var d = gmDiagDaysBetween(since, new Date().toISOString().slice(0, 19).replace("T", " "));
            if (d === null || d < 0) { return; }
            if (!stageDays[l.estagio]) { stageDays[l.estagio] = []; }
            stageDays[l.estagio].push(d);
        });
        var daysInStage = [];
        GM_DIAG_LIVE_STAGES.forEach(function(st) {
            var arr = stageDays[st] || [];
            if (!arr.length) { return; }
            var sum = 0;
            arr.forEach(function(x) { sum += x; });
            daysInStage.push({
                stage: st,
                avg_days: Math.round((sum / arr.length) * 10) / 10,
                sample: arr.length
            });
        });

        // ── Metric 6 — most common objections, ranked ───────────────────────
        // ── and the NOTE beside each one (metric 6 + the gap view) ──────────
        //
        // The note travels WITH the objection and is never collapsed into the
        // label. A rep who picks "Can't afford it" and writes "doesn't want
        // financing" has misread a buying signal as a budget objection, and
        // that gap is the single most valuable output of this feature. A
        // category count with no notes behind it cannot be read, so the API
        // never returns one without the other.
        var objCounts = {};
        var objDetail = {};
        contacts.forEach(function(c) {
            if (!c.objection) { return; }
            objCounts[c.objection] = (objCounts[c.objection] || 0) + 1;
            if (!objDetail[c.objection]) { objDetail[c.objection] = []; }
            objDetail[c.objection].push({
                lead_id: c.lead_id,
                note: c.notes || null,
                logged_by: c.logged_by || null,
                logged_at: c.logged_at,
                estagio: c.estagio
            });
        });
        // Ranked by count, but ties keep Nicole's canonical order rather than
        // falling back to alphabetical.
        var objections = Object.keys(objCounts).sort(function(a, b) {
            if (objCounts[b] !== objCounts[a]) { return objCounts[b] - objCounts[a]; }
            return GM_LEAD_OBJECTIONS.indexOf(a) - GM_LEAD_OBJECTIONS.indexOf(b);
        }).map(function(k) {
            return { objection: k, count: objCounts[k], entries: objDetail[k] };
        });

        // ── Metric 7 — objection → outcome ──────────────────────────────────
        // Which objections this seller LOSES to versus closes through. The
        // highest-value view on the page: losing every "Too expensive" while
        // closing every "Need to think about it" is a specific, coachable gap.
        var objOutcome = {};
        var leadStageById = {};
        leads.forEach(function(l) { leadStageById[l.id] = l.estagio; });
        contacts.forEach(function(c) {
            if (!c.objection) { return; }
            var st = leadStageById[c.lead_id] || c.estagio;
            if (!objOutcome[c.objection]) { objOutcome[c.objection] = { won: 0, lost: 0, open: 0 }; }
            if (st === "fechado") { objOutcome[c.objection].won++; }
            else if (st === "perdido") { objOutcome[c.objection].lost++; }
            else { objOutcome[c.objection].open++; }
        });
        var objectionOutcomes = Object.keys(objOutcome).sort(function(a, b) {
            return GM_LEAD_OBJECTIONS.indexOf(a) - GM_LEAD_OBJECTIONS.indexOf(b);
        }).map(function(k) {
            var o = objOutcome[k];
            var decided = o.won + o.lost;
            return {
                objection: k, won: o.won, lost: o.lost, open: o.open,
                decided: decided,
                win_pct: gmDiagRatio(o.won, decided, decided)
            };
        });

        // ── Metric 8 — closed vs lost counts ────────────────────────────────
        //
        // CLOSED WORK LIVES IN gm_jobs, NOT IN gm_leads.estagio='Fechado'.
        // Counting only the lead stage made this metric blind: Andrey Sans owns
        // a $64,000 signed project and has zero leads at 'Fechado', so the page
        // said "0 fechados" and 0% next to money it had itself just reported.
        // Asaf was the same at $75,000. Same family of bug as the overdue-tasks
        // tile that could not see 96% of its rows — the query structurally
        // excluded the data, so the number was not slightly off, it was blind.
        //
        // Jobs are counted where the lead never reached 'Fechado', so a deal
        // that exists in both tables is not counted twice. `jobs` is loaded
        // further down (it is also what the money tiles use); the lookup is
        // built here and consumed after that query runs.
        var wonLeads = leads.filter(function(l) { return l.estagio === "fechado"; }).length;
        var lost = leads.filter(function(l) { return l.estagio === "perdido"; }).length;

        // ── Metric 9 — average deal value on closed deals ───────────────────
        // Catches DISCOUNTING, which a closing ratio alone hides: a seller
        // closing 80% at low average value is buying deals.
        // Values come from gm_jobs for the same reason as the counts above: a
        // 'Fechado' lead here carries no valor, so averaging the lead rows
        // produced an average over an empty set. Computed after `jobs` loads.
        var closedValues = [];
        leads.forEach(function(l) {
            if (l.estagio === "fechado" && l.valor !== null && l.valor !== undefined) {
                closedValues.push(l.valor);
            }
        });
        var avgDeal = null;

        // ── Metric 10 — touches before close/loss ───────────────────────────
        //
        // Deliberately leads-only, unlike metrics 8 and 9 above: a job carries
        // no contact log, so it has no touch count to average. This measures
        // leads that were worked to a decision, which is what the tile says.
        var touchCounts = [];
        leads.forEach(function(l) {
            if (l.estagio !== "fechado" && l.estagio !== "perdido") { return; }
            var n = contacts.filter(function(c) { return c.lead_id === l.id; }).length;
            touchCounts.push(n);
        });
        var avgTouches = null;
        if (touchCounts.length >= GM_DIAG_MIN_SAMPLE) {
            var ts = 0;
            touchCounts.forEach(function(x) { ts += x; });
            avgTouches = Math.round((ts / touchCounts.length) * 10) / 10;
        }

        // ── Metric 11 — MONEY: won, still in play, and lost ─────────────────
        //
        // Three figures, and they are returned and rendered in this order:
        // closed, active pipeline, lost. Won FIRST is deliberate. A page that
        // leads with the lost total and buries the closed one reads as an
        // indictment of the sales team rather than as a diagnostic, and this
        // page names individual employees.
        //
        // COVERAGE IS PART OF EVERY FIGURE, NOT A FOOTNOTE. Most leads carry no
        // valor at all, so each total ships with the count that actually
        // contributed AND the count of leads in that bucket. A sum over 11 of
        // 58 lost leads is a partial minimum, not "the amount this business
        // lost", and the UI cannot say so unless the API hands it both numbers.
        //
        // NO RATIOS HERE, ON PURPOSE. See the note on per-seller rows below.
        function gmDiagMoney(rows) {
            var sum = 0, withValue = 0;
            rows.forEach(function(l) {
                if (l.valor !== null && l.valor !== undefined && l.valor > 0) {
                    sum += l.valor; withValue++;
                }
            });
            return { total: sum, with_value: withValue, leads: rows.length };
        }

        // Largest single win/loss, carrying the deal name so the number is
        // traceable to a real job instead of floating free.
        //
        // gm_jobs.obra is not a tidy name: the spreadsheet import concatenated
        // the customer, the scope, the salesperson and a paragraph of notes
        // into one field. Taking it whole would dump that paragraph into a
        // tile, so the label is cut at the first sentence-ish boundary and
        // capped. The full text is still on the job record itself.
        function gmDiagDealLabel(s) {
            if (!s) { return null; }
            var txt = String(s).trim();
            var cut = txt.split(/\s+[—–-]\s+|\.\s/)[0].trim();
            if (!cut) { cut = txt; }
            if (cut.length > 60) { cut = cut.slice(0, 57).trim() + "…"; }
            return cut;
        }

        function gmDiagBiggest(rows) {
            var best = null;
            rows.forEach(function(l) {
                if (l.valor === null || l.valor === undefined || l.valor <= 0) { return; }
                if (!best || l.valor > best.valor) { best = l; }
            });
            return best ? { valor: best.valor, nome: gmDiagDealLabel(best.nome) } : null;
        }

        var lostLeads = leads.filter(function(l) { return l.estagio === "perdido"; });
        var activeLeads = leads.filter(function(l) {
            return l.estagio !== "perdido" && l.estagio !== "fechado";
        });

        // WON comes from gm_jobs, not from gm_leads: a job is the signed work,
        // and gm_jobs.vendedor is backfilled. gm_leads.estagio='Fechado' is a
        // pipeline state that mostly predates the jobs table here and carries
        // no value, so summing it would under-report what was actually sold.
        var jobBinds = sellerFilter ? [id, sellerFilter] : [id];
        var jobRows = await env.DB.prepare(
            "SELECT obra AS nome, vendedor, valor FROM gm_jobs WHERE client_id = ?" +
            (sellerFilter ? " AND vendedor = ?" : "")
        ).bind(...jobBinds).all();
        var jobs = jobRows.results || [];

        var wonMoney = gmDiagMoney(jobs);
        var activeMoney = gmDiagMoney(activeLeads);
        var lostMoney = gmDiagMoney(lostLeads);

        // ── Metrics 8 and 9, completed now that gm_jobs is loaded ───────────
        //
        // Signed jobs are the closed work. Only one lead in the whole database
        // sits at 'Fechado' (a test row, no value), so before this the closed
        // count and the average deal value were both computed over an empty
        // set while gm_jobs held the real thing.
        var won = wonLeads + jobs.length;

        // The average is over jobs that actually carry a value, and still
        // refuses to answer below the sample threshold.
        var jobValues = [];
        jobs.forEach(function(j) {
            if (j.valor !== null && j.valor !== undefined && j.valor > 0) { jobValues.push(j.valor); }
        });
        var allClosedValues = closedValues.concat(jobValues);
        if (allClosedValues.length >= GM_DIAG_MIN_SAMPLE) {
            var vs = 0;
            allClosedValues.forEach(function(v) { vs += v; });
            avgDeal = Math.round((vs / allClosedValues.length) * 100) / 100;
        }

        // ── Closing ratio: closes ÷ that seller's own leads ─────────────────
        //
        // The denominator is every lead assigned to the seller, not just the
        // decided ones: a lead that belonged to them and never closed is part
        // of what they were given to work. Nicole's call — a lost lead that
        // belonged to a seller is that seller's lost lead, and that is the
        // data rather than a sampling artifact.
        //
        // The denominator is ALWAYS returned and rendered beside the figure
        // ("1 de 15"), never behind a tooltip, so the ratio can be read
        // against what it was computed over. The only gate left is the
        // existing small-sample threshold, applied to the denominator.
        var leadsForDenominator = leads.length;
        var closingPct = gmDiagRatio(won, leadsForDenominator, leadsForDenominator);

        // ── Per-seller money rows, sorted by CLOSED value descending ────────
        //
        // Sorted by what each person SOLD, not by what they lost. Same reason
        // won renders first.
        //
        // THERE IS DELIBERATELY NO CLOSE RATE OR WIN/LOSS RATIO ON THESE ROWS.
        // This client's lead data was imported from three spreadsheet tabs with
        // completely different sampling — one of them, CANCELADOS, contains
        // cancelled deals ONLY. A seller whose leads came mostly from that tab
        // reads as 15 lost / 0 active purely because of where the rows came
        // from, while having closed real work that lives in gm_jobs. Any ratio
        // built on those denominators would characterise a named employee off a
        // sampling artifact, on a page whose whole reason for being admin-only
        // is that it names people. So the rows carry counts and money, and the
        // reader does their own thinking.
        //
        // `origem_concentration` exists to make that visible rather than
        // implied: where a seller's leads come overwhelmingly from one source,
        // the row says so, so nobody reads a lopsided row as performance.
        var origemRows = await env.DB.prepare(
            "SELECT vendedor, origem, COUNT(*) AS n FROM gm_leads " +
            "WHERE client_id = ? AND vendedor IS NOT NULL AND vendedor <> '' " +
            "GROUP BY vendedor, origem"
        ).bind(id).all();
        var origemBySeller = {};
        (origemRows.results || []).forEach(function(r) {
            if (!origemBySeller[r.vendedor]) { origemBySeller[r.vendedor] = []; }
            origemBySeller[r.vendedor].push({ origem: r.origem || "(sem origem)", n: r.n });
        });

        var sellerMoney = sellers.map(function(name) {
            var theirLost = lostLeads.filter(function(l) { return l.vendedor === name; });
            var theirActive = activeLeads.filter(function(l) { return l.vendedor === name; });
            var theirJobs = jobs.filter(function(j) { return j.vendedor === name; });

            // Dominant origem, only when it genuinely dominates. The threshold
            // is on the seller's own lead count, and it is reported with both
            // numbers so it reads as provenance, never as a score.
            var conc = null;
            var mine = origemBySeller[name] || [];
            var totalOrigem = 0;
            mine.forEach(function(o) { totalOrigem += o.n; });
            if (totalOrigem > 0) {
                var top = mine.slice().sort(function(a, b) { return b.n - a.n; })[0];
                if (top && top.n / totalOrigem >= 0.6) {
                    conc = {
                        origem: top.origem, count: top.n, of: totalOrigem,
                        pct: Math.round((top.n / totalOrigem) * 100)
                    };
                }
            }

            return {
                seller: name,
                won: gmDiagMoney(theirJobs),
                active: gmDiagMoney(theirActive),
                lost: gmDiagMoney(theirLost),
                biggest_win: gmDiagBiggest(theirJobs),
                biggest_loss: gmDiagBiggest(theirLost),
                origem_concentration: conc
            };
        }).sort(function(a, b) {
            // Closed value descending. Ties fall back to name so the order is
            // stable between loads rather than depending on roster ordering.
            if (b.won.total !== a.won.total) { return b.won.total - a.won.total; }
            return a.seller.localeCompare(b.seller);
        });

        return jsonOk({
            client_id: id,
            client_name: client.name,
            seller: sellerFilter || null,
            sellers: sellers,
            seat_count: Object.keys(seatNames).length,
            min_sample: GM_DIAG_MIN_SAMPLE,
            metrics: {
                speed_to_first_contact: {
                    median_minutes: gmDiagMedian(firstContactMins),
                    sla_minutes: 5,
                    breaches: slaContactBreaches,
                    sample: firstContactMins.length
                },
                speed_to_estimate: {
                    median_hours: gmDiagMedian(estimateHrs),
                    sla_hours: 24,
                    breaches: slaEstimateBreaches,
                    sample: estimateHrs.length
                },
                contact_ratio: {
                    attempts: attempts,
                    answered: answered,
                    // Attempts per conversation reached. The threshold applies
                    // to ANSWERED, not to attempts: answered is the ratio's
                    // DENOMINATOR, and it is the thin number here. Gating on
                    // attempts would report "2.7 attempts per conversation"
                    // off three conversations — precisely the small-sample
                    // number this rule exists to suppress. The raw attempts
                    // and answered counts are still returned, so the page can
                    // show the underlying activity without implying a rate.
                    ratio: (answered >= GM_DIAG_MIN_SAMPLE)
                               ? Math.round((attempts / answered) * 10) / 10 : null,
                    sample: answered
                },
                outcome_after_conversation: {
                    advanced: advancedAfter,
                    stalled: stalledAfter,
                    advanced_pct: gmDiagRatio(advancedAfter, advancedAfter + stalledAfter,
                                              advancedAfter + stalledAfter),
                    sample: advancedAfter + stalledAfter
                },
                days_in_stage: { stages: daysInStage, sample: leads.filter(function(l) {
                    return GM_DIAG_LIVE_STAGES.indexOf(l.estagio) >= 0; }).length },
                objections: { ranked: objections, sample: contacts.filter(function(c) {
                    return !!c.objection; }).length },
                objection_outcomes: { rows: objectionOutcomes, sample: contacts.filter(function(c) {
                    return !!c.objection; }).length },
                closing_ratio: {
                    won: won, lost: lost, decided: won + lost,
                    won_jobs: jobs.length, won_leads: wonLeads,
                    pct: closingPct,
                    // The ratio's denominator: every lead assigned to this
                    // seller. Rendered beside the percentage, never hidden.
                    of_leads: leadsForDenominator,
                    sample: leadsForDenominator
                },
                // Sample counts the values the average was actually taken
                // over — jobs included — so the printed sample can never
                // disagree with the number beside it.
                average_deal_value: { value: avgDeal, sample: allClosedValues.length },
                touches_before_close: { avg: avgTouches, sample: touchCounts.length },
                // Order here mirrors render order: won, active, lost.
                money: {
                    won: wonMoney,
                    active: activeMoney,
                    lost: lostMoney,
                    biggest_win: gmDiagBiggest(jobs),
                    biggest_loss: gmDiagBiggest(lostLeads),
                    by_seller: sellerMoney
                }
            }
        });
    } catch (e) {
        return jsonErr("Error building seller diagnostics: " + e.message, 500);
    }
}

async function handleGetGmJobs(id, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        var config = await gmGetConfig(env, id);
        var rows = await env.DB.prepare(
            "SELECT * FROM gm_jobs WHERE client_id = ? ORDER BY created_at DESC"
        ).bind(id).all();
        var jobs = [];
        (rows.results || []).forEach(function(r) {
            var computed = gmJobComputed(r, config.target_margin);
            var out = {};
            Object.keys(r).forEach(function(k) { out[k] = r[k]; });
            Object.keys(computed).forEach(function(k) { out[k] = computed[k]; });
            jobs.push(out);
        });
        return jsonOk({ jobs: jobs, target_margin: config.target_margin });
    } catch (e) {
        return jsonErr("Error fetching jobs: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Project photos — gm_job_photos + R2.
//
// Asked for by Rafa. For a pool builder the project is a physical site, and
// progress photos are what an owner shows their own customer, so these are
// CLIENT-VISIBLE by design.
//
// SELLERS CANNOT SEE THEM. Nothing here enforces that, and nothing here needs
// to: sellerRequestAllowed() is a strict allowlist and these routes are simply
// absent from it, so a seller session is refused before reaching any handler.
// Adding a photo route to that allowlist would be the mistake.
//
// Key layout mirrors client-documents: job-photos/<clientId>/<photoId>.<ext>.
// ---------------------------------------------------------------------------

// The table is named gm_job_photos and now holds PDFs too — the client asked
// for documents on projects after photos were already shipping. See
// migrations/gm_job_files.sql for why the name was not changed.
var JOB_PHOTO_TYPES = {
    "image/jpeg": "jpg", "image/jpg": "jpg", "image/png": "png",
    "image/gif": "gif", "image/webp": "webp", "image/heic": "heic",
    "application/pdf": "pdf"
};

// Phones produce large files. 15 MB accepts a modern phone photo without
// resizing while still refusing something pathological.
var JOB_PHOTO_MAX_BYTES = 15 * 1024 * 1024;

// Is this attachment an image (thumbnail) or a document (file row)?
//
// NULL counts as an image: rows predating the content_type column are all
// images, and gm_job_files.sql backfills them — this keeps a row that somehow
// escaped the backfill rendering exactly as it does today rather than turning
// into a broken file entry.
function gmIsImageType(contentType) {
    if (!contentType) { return true; }
    return String(contentType).slice(0, 6) === "image/";
}

// One shape for every attachment row the API returns. file_url is an API
// path, not an R2 key — raw R2 paths are never exposed to the frontend.
function gmJobPhotoOut(row, clientId) {
    return {
        id: row.id,
        job_id: row.job_id,
        caption: row.caption || null,
        uploaded_by: row.uploaded_by || null,
        created_at: row.created_at,
        // Both null on pre-widening rows; the frontend treats that as an image.
        content_type: row.content_type || null,
        file_name: row.file_name || null,
        is_image: gmIsImageType(row.content_type),
        file_url: "/api/clients/" + clientId + "/gm/jobs/" + row.job_id + "/photos/" + row.id + "/file"
    };
}

// Confirms the job belongs to this client before anything touches a photo, so
// a guessed job_id from another client cannot be read or written through.
async function gmJobBelongsToClient(env, clientId, jobId) {
    var row = await env.DB.prepare(
        "SELECT id FROM gm_jobs WHERE id = ? AND client_id = ?"
    ).bind(jobId, clientId).first();
    return !!row;
}

async function handleGetGmJobPhotos(id, jobId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        if (!(await gmJobBelongsToClient(env, id, jobId))) { return jsonErr("Project not found", 404); }

        var rows = await env.DB.prepare(
            "SELECT * FROM gm_job_photos WHERE job_id = ? AND client_id = ? ORDER BY created_at ASC"
        ).bind(jobId, id).all();

        return jsonOk({
            photos: (rows.results || []).map(function(r) { return gmJobPhotoOut(r, id); })
        });
    } catch (e) {
        return jsonErr("Error fetching project photos: " + e.message, 500);
    }
}

async function handlePostGmJobPhoto(id, jobId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        if (!(await gmJobBelongsToClient(env, id, jobId))) { return jsonErr("Project not found", 404); }

        var form = await request.formData();
        var file = form.get("photo");
        if (!file || typeof file.arrayBuffer !== "function") {
            return jsonErr("photo is required", 400);
        }

        var ext = JOB_PHOTO_TYPES[file.type];
        if (!ext) {
            return jsonErr("Invalid file type. Upload a PDF or a JPG, PNG, GIF, WebP or HEIC image.", 400);
        }

        var buf = await file.arrayBuffer();
        if (buf.byteLength > JOB_PHOTO_MAX_BYTES) {
            return jsonErr("File too large. Maximum size is 15 MB.", 400);
        }

        var capField = form.get("caption");
        var caption = (typeof capField === "string" && capField.trim()) ? capField.trim().slice(0, 300) : null;

        // The name the file arrived with, kept so a PDF row can be identified
        // in the gallery. Never used to build the R2 key (that comes from the
        // validated type allowlist above) and never trusted as a path: strip
        // any directory part and cap the length.
        var nameField = (file.name && typeof file.name === "string") ? file.name : "";
        var fileName = nameField.split(/[\\/]/).pop().trim().slice(0, 200) || null;

        var photoId = crypto.randomUUID();
        var key = "job-photos/" + id + "/" + photoId + "." + ext;

        await env.ASSETS.put(key, buf, { httpMetadata: { contentType: file.type } });

        await env.DB.prepare(
            "INSERT INTO gm_job_photos (id, job_id, client_id, r2_key, caption, uploaded_by, content_type, file_name) " +
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
        ).bind(
            photoId, jobId, id, key, caption,
            user.display_name || user.role || null,
            file.type, fileName
        ).run();

        var row = await env.DB.prepare("SELECT * FROM gm_job_photos WHERE id = ?").bind(photoId).first();
        return jsonOk({ photo: gmJobPhotoOut(row, id) });
    } catch (e) {
        return jsonErr("Error uploading photo: " + e.message, 500);
    }
}

async function handleGetGmJobPhotoFile(id, jobId, photoId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }

        // Scoped by client AND job: an id from another client's project is a
        // 404 here, not a served file.
        var row = await env.DB.prepare(
            "SELECT r2_key, content_type, file_name FROM gm_job_photos WHERE id = ? AND job_id = ? AND client_id = ?"
        ).bind(photoId, jobId, id).first();
        if (!row) { return jsonErr("Photo not found", 404); }

        // Same guard as the documents route: never hand R2 a path shape we did
        // not write ourselves.
        if (!/^job-photos\/[A-Za-z0-9_-]+\/[A-Za-z0-9-]+\.[a-z0-9]+$/.test(row.r2_key)) {
            return jsonErr("Photo not found", 404);
        }

        var obj = await env.ASSETS.get(row.r2_key);
        if (!obj) { return jsonErr("Photo not found", 404); }

        var headers = new Headers();
        headers.set("Content-Type",
            (obj.httpMetadata && obj.httpMetadata.contentType) || row.content_type || "image/jpeg");
        headers.set("Cache-Control", "private, max-age=3600");
        // Images render inline as before. A PDF opens in the browser's own
        // viewer, but carries its original name so a "save" lands as
        // "estimate-jm.pdf" rather than a bare UUID. Quotes escaped, and the
        // name is already stripped of any path at upload.
        if (!gmIsImageType(row.content_type) && row.file_name) {
            headers.set("Content-Disposition",
                'inline; filename="' + String(row.file_name).replace(/["\\]/g, "") + '"');
        }
        return new Response(obj.body, { headers: headers });
    } catch (e) {
        return jsonErr("Error fetching photo: " + e.message, 500);
    }
}

async function handleDeleteGmJobPhoto(id, jobId, photoId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }

        var row = await env.DB.prepare(
            "SELECT r2_key FROM gm_job_photos WHERE id = ? AND job_id = ? AND client_id = ?"
        ).bind(photoId, jobId, id).first();
        if (!row) { return jsonErr("Photo not found", 404); }

        if (!/^job-photos\/[A-Za-z0-9_-]+\/[A-Za-z0-9-]+\.[a-z0-9]+$/.test(row.r2_key)) {
            return jsonErr("Photo not found", 404);
        }

        // The R2 object goes first. If the row were dropped first and this
        // threw, the object would be orphaned with nothing left pointing at
        // it — unreachable and undeletable through the API.
        await env.ASSETS.delete(row.r2_key);

        await env.DB.prepare(
            "DELETE FROM gm_job_photos WHERE id = ? AND job_id = ? AND client_id = ?"
        ).bind(photoId, jobId, id).run();

        return jsonOk({ deleted: true });
    } catch (e) {
        return jsonErr("Error deleting photo: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Lead attachments — gm_lead_files + R2.
//
// Asked for by Rafa in the client's words: archive "PDF ou fotos" against a
// lead — the signed estimate, a permit, site photos from WhatsApp.
//
// Built on the gm_job_photos pattern one tier over, carrying the same safety
// properties deliberately: client-scoped reads, a strict r2_key regex before
// R2 is touched, and a delete that removes the object AND the row.
//
// SELLERS CANNOT REACH THESE ROUTES. sellerRequestAllowed() is a strict
// allowlist and none of these paths are in it, so a seller session is refused
// before any handler runs. Adding one there would be the mistake.
//
// Key layout mirrors the job photos: lead-files/<leadId>/<fileId>.<ext>.
// ---------------------------------------------------------------------------

// Images plus PDF, because the ask was explicitly "PDF ou fotos".
var LEAD_FILE_TYPES = {
    "image/jpeg": "jpg", "image/jpg": "jpg", "image/png": "png",
    "image/gif": "gif", "image/webp": "webp", "image/heic": "heic",
    "application/pdf": "pdf"
};

// Same ceiling as project photos: a modern phone photo or a scanned estimate
// fits; something pathological does not.
var LEAD_FILE_MAX_BYTES = 15 * 1024 * 1024;

// Keyed on the lead, so a guessed id from another business cannot be written
// through or read back.
async function gmLeadBelongsToClient(env, clientId, leadId) {
    var row = await env.DB.prepare(
        "SELECT id FROM gm_leads WHERE id = ? AND client_id = ?"
    ).bind(leadId, clientId).first();
    return !!row;
}

// A SELLER may only touch their OWN leads — the same contract
// handleGetGmLeadContacts enforces inline (lead.vendedor !== cSeller → 403).
//
// This exists because notes and lead files were opened to the portal
// allowlists so a salesperson can work a lead end to end: they own it, they
// carry the customer relationship, and they are paid commission on it. But
// the allowlist only controls WHICH ROUTES a session may call — without this,
// any of JM's four sellers could read and edit notes and files on every other
// seller's leads. This is what controls WHICH ROWS.
//
// Returns an error Response to hand straight back, or null when the caller may
// proceed. sessionSellerName is null for admins and for owner (non-seller)
// client sessions, so this is a no-op on every path except a seller session.
async function gmSellerLeadGuard(env, user, clientId, leadId) {
    var seller = sessionSellerName(user);
    if (!seller) { return null; }
    var lead = await env.DB.prepare(
        "SELECT vendedor FROM gm_leads WHERE id = ? AND client_id = ?"
    ).bind(leadId, clientId).first();
    if (!lead) { return jsonErr("Lead not found", 404); }
    if (lead.vendedor !== seller) { return jsonErr("Forbidden", 403); }
    return null;
}

function gmLeadFileOut(row, clientId) {
    return {
        id: row.id,
        lead_id: row.lead_id,
        caption: row.caption || null,
        file_name: row.file_name || null,
        content_type: row.content_type,
        is_image: gmIsImageType(row.content_type),
        uploaded_by: row.uploaded_by || null,
        created_at: row.created_at,
        file_url: "/api/clients/" + clientId + "/gm/leads/" + row.lead_id + "/files/" + row.id + "/file"
    };
}

async function handleGetGmLeadFiles(id, leadId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        if (!(await gmLeadBelongsToClient(env, id, leadId))) { return jsonErr("Lead not found", 404); }
        var sellerBlock = await gmSellerLeadGuard(env, user, id, leadId);
        if (sellerBlock) { return sellerBlock; }

        var rows = await env.DB.prepare(
            "SELECT * FROM gm_lead_files WHERE lead_id = ? AND client_id = ? ORDER BY created_at ASC"
        ).bind(leadId, id).all();

        return jsonOk({
            files: (rows.results || []).map(function(r) { return gmLeadFileOut(r, id); })
        });
    } catch (e) {
        return jsonErr("Error fetching lead files: " + e.message, 500);
    }
}

async function handlePostGmLeadFile(id, leadId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        if (!(await gmLeadBelongsToClient(env, id, leadId))) { return jsonErr("Lead not found", 404); }
        var sellerBlock = await gmSellerLeadGuard(env, user, id, leadId);
        if (sellerBlock) { return sellerBlock; }

        var form = await request.formData();
        var file = form.get("file");
        if (!file || typeof file.arrayBuffer !== "function") {
            return jsonErr("file is required", 400);
        }

        var ext = LEAD_FILE_TYPES[file.type];
        if (!ext) {
            return jsonErr("Invalid file type. Upload a PDF or a JPG, PNG, GIF, WebP or HEIC image.", 400);
        }

        var buf = await file.arrayBuffer();
        if (buf.byteLength > LEAD_FILE_MAX_BYTES) {
            return jsonErr("File too large. Maximum size is 15 MB.", 400);
        }

        var capField = form.get("caption");
        var caption = (typeof capField === "string" && capField.trim()) ? capField.trim().slice(0, 300) : null;

        // Kept for display only. The R2 key is built from the validated type
        // above, never from this; any directory part is stripped so a name
        // like "../../x.pdf" cannot influence a path.
        var nameField = (file.name && typeof file.name === "string") ? file.name : "";
        var fileName = nameField.split(/[\\/]/).pop().trim().slice(0, 200) || null;

        var fileId = crypto.randomUUID();
        var key = "lead-files/" + leadId + "/" + fileId + "." + ext;

        await env.ASSETS.put(key, buf, { httpMetadata: { contentType: file.type } });

        await env.DB.prepare(
            "INSERT INTO gm_lead_files (id, lead_id, client_id, r2_key, file_name, content_type, caption, uploaded_by) " +
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?)"
        ).bind(
            fileId, leadId, id, key, fileName, file.type, caption,
            user.display_name || user.role || null
        ).run();

        var row = await env.DB.prepare("SELECT * FROM gm_lead_files WHERE id = ?").bind(fileId).first();
        return jsonOk({ file: gmLeadFileOut(row, id) });
    } catch (e) {
        return jsonErr("Error uploading file: " + e.message, 500);
    }
}

async function handleGetGmLeadFileContent(id, leadId, fileId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }

        var sellerBlock = await gmSellerLeadGuard(env, user, id, leadId);
        if (sellerBlock) { return sellerBlock; }

        // Scoped by client AND lead: an id from another client's lead is a 404
        // here, not a served file.
        var row = await env.DB.prepare(
            "SELECT r2_key, content_type, file_name FROM gm_lead_files WHERE id = ? AND lead_id = ? AND client_id = ?"
        ).bind(fileId, leadId, id).first();
        if (!row) { return jsonErr("File not found", 404); }

        // Never hand R2 a path shape we did not write ourselves.
        if (!/^lead-files\/[A-Za-z0-9_-]+\/[A-Za-z0-9-]+\.[a-z0-9]+$/.test(row.r2_key)) {
            return jsonErr("File not found", 404);
        }

        var obj = await env.ASSETS.get(row.r2_key);
        if (!obj) { return jsonErr("File not found", 404); }

        var headers = new Headers();
        headers.set("Content-Type",
            (obj.httpMetadata && obj.httpMetadata.contentType) || row.content_type || "application/octet-stream");
        headers.set("Cache-Control", "private, max-age=3600");
        if (!gmIsImageType(row.content_type) && row.file_name) {
            headers.set("Content-Disposition",
                'inline; filename="' + String(row.file_name).replace(/["\\]/g, "") + '"');
        }
        return new Response(obj.body, { headers: headers });
    } catch (e) {
        return jsonErr("Error fetching file: " + e.message, 500);
    }
}

async function handleDeleteGmLeadFile(id, leadId, fileId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }

        var sellerBlock = await gmSellerLeadGuard(env, user, id, leadId);
        if (sellerBlock) { return sellerBlock; }

        var row = await env.DB.prepare(
            "SELECT r2_key FROM gm_lead_files WHERE id = ? AND lead_id = ? AND client_id = ?"
        ).bind(fileId, leadId, id).first();
        if (!row) { return jsonErr("File not found", 404); }

        if (!/^lead-files\/[A-Za-z0-9_-]+\/[A-Za-z0-9-]+\.[a-z0-9]+$/.test(row.r2_key)) {
            return jsonErr("File not found", 404);
        }

        // The R2 object goes first. If the row were dropped first and this
        // threw, the object would be orphaned with nothing pointing at it —
        // unreachable and undeletable through the API.
        await env.ASSETS.delete(row.r2_key);

        await env.DB.prepare(
            "DELETE FROM gm_lead_files WHERE id = ? AND lead_id = ? AND client_id = ?"
        ).bind(fileId, leadId, id).run();

        return jsonOk({ deleted: true });
    } catch (e) {
        return jsonErr("Error deleting file: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// The client business's own calendar — gm_events.
//
// Native to the client tier. NO GOOGLE: no OAuth, no sync, no integration.
// That was an explicit decision (see migrations/gm_events.sql), not a gap.
//
// The month payload carries three kinds of entry and the frontend renders
// them differently because they mean different things:
//
//   own      — a gm_events row. Editable, deletable.
//   derived  — read from gm_jobs at request time, NEVER stored. A project
//              shows on its start date and its deadline. Not editable here:
//              the job is edited on the job, and a mirrored gm_events row
//              would drift the moment someone moved a deadline.
//   club     — an Apex Club invitation. Apex-tier data, read-only, and
//              stripped to invitation fields only. See the block below.
//
// Sellers reach none of it: sellerRequestAllowed() does not list these paths.
// ---------------------------------------------------------------------------

// A YYYY-MM-DD string, or null. Rejects anything else rather than letting a
// malformed date into a column the month query filters on with string
// comparison.
function gmDateStr(v) {
    var s = gmStr(v, 10);
    if (!s || !/^\d{4}-\d{2}-\d{2}$/.test(s)) { return null; }
    return s;
}

// HH:MM, or null. Accepts HH:MM:SS from a time input and drops the seconds.
function gmTimeStr(v) {
    var s = gmStr(v, 8);
    if (!s) { return null; }
    var m = /^(\d{2}):(\d{2})(:\d{2})?$/.exec(s);
    if (!m) { return null; }
    var h = parseInt(m[1], 10), mi = parseInt(m[2], 10);
    if (h > 23 || mi > 59) { return null; }
    return m[1] + ":" + m[2];
}

function gmEventOut(row) {
    return {
        kind: "own",
        id: row.id,
        event_type: row.event_type,
        title: row.title,
        // Stored, never inferred by comparing the saved title against a
        // freshly generated one — that comparison flips to "overridden" the
        // moment a translation is corrected. An event whose title is NOT
        // overridden has its title recomposed per language by the frontend
        // from event_type + job_id/lead_id.
        title_overridden: row.title_overridden === 1,
        date: row.event_date,
        start_time: row.start_time || null,
        end_time: row.end_time || null,
        all_day: row.all_day === 1,
        location: row.location || null,
        description: row.description || null,
        job_id: row.job_id || null,
        lead_id: row.lead_id || null,
        assigned_to: row.assigned_to || null,
        created_by: row.created_by || null,
        created_at: row.created_at,
        updated_by: row.updated_by || null,
        updated_at: row.updated_at,
        editable: true
    };
}

// Validates and normalises a create/update body. Returns { error } or fields.
// The linked job/lead are re-checked against THIS client, so a guessed id from
// another business cannot be attached to an event.
async function gmEventFields(env, clientId, body, partial) {
    var out = {};
    function has(k) { return Object.prototype.hasOwnProperty.call(body, k); }

    if (!partial || has("event_type")) {
        var et = gmStr(body.event_type, 80);
        if (!et) { return { error: "O tipo de evento é obrigatório / Event type is required" }; }
        out.event_type = et;
    }
    if (!partial || has("title")) {
        var t = gmStr(body.title, 300);
        if (!t) { return { error: "O título é obrigatório / Title is required" }; }
        out.title = t;
    }
    if (!partial || has("event_date")) {
        var d = gmDateStr(body.event_date);
        if (!d) { return { error: "Data inválida / Invalid date" }; }
        out.event_date = d;
    }
    if (has("start_time")) { out.start_time = gmTimeStr(body.start_time); }
    if (has("end_time"))   { out.end_time   = gmTimeStr(body.end_time); }
    if (has("all_day"))    { out.all_day    = body.all_day ? 1 : 0; }
    if (has("title_overridden")) { out.title_overridden = body.title_overridden ? 1 : 0; }
    if (has("location"))    { out.location    = gmStr(body.location, 300); }
    if (has("description")) { out.description = gmStr(body.description, 4000); }
    if (has("assigned_to")) { out.assigned_to = gmStr(body.assigned_to, 120); }

    if (has("job_id")) {
        var jid = gmStr(body.job_id, 80);
        if (jid) {
            var j = await env.DB.prepare("SELECT id FROM gm_jobs WHERE id = ? AND client_id = ?")
                .bind(jid, clientId).first();
            if (!j) { return { error: "Projeto não encontrado / Project not found" }; }
        }
        out.job_id = jid;
    }
    if (has("lead_id")) {
        var lid = gmStr(body.lead_id, 80);
        if (lid) {
            var l = await env.DB.prepare("SELECT id FROM gm_leads WHERE id = ? AND client_id = ?")
                .bind(lid, clientId).first();
            if (!l) { return { error: "Lead não encontrado / Lead not found" }; }
        }
        out.lead_id = lid;
    }
    // An all-day event has no clock times; storing them would render a time
    // on a chip that the form said had none.
    if (out.all_day === 1) { out.start_time = null; out.end_time = null; }
    return out;
}

// Projects rendered onto the calendar, DERIVED at read time from gm_jobs.
//
// Never written into gm_events: a mirrored row drifts from the job the moment
// somebody moves a deadline, and then two records disagree with no way to tell
// which is right. Each entry carries job_id so a tap opens the job itself.
//
// entrega_real (actual delivery) is included alongside the planned dates —
// it is a real, dated, client-owned fact, and on a finished job it is the date
// the owner actually cares about.
async function gmDerivedJobEvents(env, clientId, fromDate, toDate) {
    var rows = await env.DB.prepare(
        "SELECT id, obra, inicio, prazo_previsto, entrega_real, status FROM gm_jobs " +
        "WHERE client_id = ? AND (" +
        "  (inicio         IS NOT NULL AND inicio         >= ? AND inicio         <= ?) OR " +
        "  (prazo_previsto IS NOT NULL AND prazo_previsto >= ? AND prazo_previsto <= ?) OR " +
        "  (entrega_real   IS NOT NULL AND entrega_real   >= ? AND entrega_real   <= ?))"
    ).bind(clientId, fromDate, toDate, fromDate, toDate, fromDate, toDate).all();

    var out = [];
    (rows.results || []).forEach(function (j) {
        // Each date gets its OWN entry, labelled, so a glance at the day says
        // which of the three it is rather than just naming the project twice.
        function push(dateVal, labelPt, labelEn, slot) {
            if (!dateVal || dateVal < fromDate || dateVal > toDate) { return; }
            out.push({
                kind: "derived",
                source: "job",
                id: "job:" + j.id + ":" + slot,
                job_id: j.id,
                date: String(dateVal).slice(0, 10),
                label_pt: labelPt,
                label_en: labelEn,
                title: j.obra,
                status: j.status || null,
                all_day: true,
                editable: false
            });
        }
        push(j.inicio,         "Início",  "Start",    "inicio");
        push(j.prazo_previsto, "Prazo",   "Deadline", "prazo");
        push(j.entrega_real,   "Entrega", "Delivered", "entrega");
    });
    return out;
}

// ---------------------------------------------------------------------------
// Apex Club invitations for a client business — A TIER BOUNDARY CROSSING.
//
// Apex Club is the one thing every client business has in common, so the
// events show on every client's calendar. They live on the APEX tier
// (apex_club_events) and the client portal is otherwise walled off from that
// data, so this is a narrow, deliberate exception.
//
// WHAT GOES OUT: name, date, start time, venue, speakers, whether a flyer
// exists, and the public registration link. That is the invitation, and all
// of it is already public — the same information printed on a flyer forwarded
// through WhatsApp groups.
//
// WHAT MUST NEVER GO OUT, and why this is a dedicated endpoint rather than a
// filter over an Apex-tier route:
//   * price / revenue / cost / P&L — price_single_cents, price_couple_cents
//     and everything in apex_club_event_txns
//   * the guest list, registrations, or headcount (apex_club_registrations)
//   * anything from transactions
// Filtering in the frontend would mean shipping the full row to the browser,
// where a client can read the money straight out of the network response. The
// SELECT below is the enforcement: the columns simply are not fetched.
//
// Precedent: the club build already renders one row three ways — Alice's
// finance view has the P&L, Rafa's calendar view has flyer + count + guest
// list and no money, and a client business is the third and narrowest
// audience: invitation only, no money AND no counts.
//
// Read-only by construction: there is no client-reachable write route for
// apex_club_events anywhere.
// ---------------------------------------------------------------------------
async function gmClubInviteEvents(env, fromDate, toDate) {
    var rows = await env.DB.prepare(
        // Explicit column list, never SELECT *. A future money column added to
        // apex_club_events must not silently start flowing to clients.
        "SELECT id, name, event_date, start_time, venue, speakers, flyer_r2_key " +
        "FROM apex_club_events WHERE event_date >= ? AND event_date <= ? " +
        "ORDER BY event_date ASC"
    ).bind(fromDate, toDate).all();

    return (rows.results || []).map(function (e) {
        return {
            kind: "club",
            id: "club:" + e.id,
            club_event_id: e.id,
            date: String(e.event_date).slice(0, 10),
            title: e.name,
            start_time: e.start_time || null,
            venue: e.venue || null,
            speakers: e.speakers || null,
            // A boolean, not the R2 key: the flyer is served by its own
            // auth-free public route, and the key is an internal path.
            has_flyer: !!e.flyer_r2_key,
            flyer_url: e.flyer_r2_key ? "/api/club/flyer/" + e.id : null,
            register_url: "club.html?e=" + e.id,
            all_day: !e.start_time,
            editable: false
        };
    });
}

// The client's meetings WITH APEX, for their own company calendar.
//
// A client books a time with Rafa and it appeared nowhere on their agenda —
// the one calendar they actually look at — so the meeting sat only on the
// portal's first screen and in Google. It belongs alongside everything else
// they have that week.
//
// Read-only (editable:false), like the club kind: rescheduling goes through the
// booking link, never by dragging a chip on their own calendar.
async function gmApexMeetingEvents(env, clientId, fromDate, toDate) {
    var rows = await env.DB.prepare(
        "SELECT id, date, time, session_type, location, google_meet_link " +
        "FROM sessions WHERE client_id = ? AND date >= ? AND date <= ? " +
        "AND status != 'cancelled' AND status != 'discarded' AND meeting_category != 'event' " +
        "ORDER BY date ASC, time ASC"
    ).bind(clientId, fromDate, toDate).all();

    return (rows.results || []).map(function (s) {
        return {
            kind: "apex",
            id: "apex:" + s.id,
            session_id: s.id,
            date: String(s.date).slice(0, 10),
            // Titled in Portuguese: the label the client reads on their own
            // calendar, matching how the portal names this meeting elsewhere.
            title: "Reunião com a Apex",
            start_time: s.time || null,
            all_day: !s.time,
            location: s.location || null,
            meet_link: s.google_meet_link || null,
            editable: false
        };
    });
}

// GET /api/clients/:id/gm/events?month=YYYY-MM
// Returns the client's own events plus derived job dates plus Apex Club
// invitations plus their Apex meetings for that month, in one payload.
async function handleGetGmEvents(id, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }

        var url = new URL(request.url);
        var month = gmStr(url.searchParams.get("month"), 7);
        if (!month || !/^\d{4}-\d{2}$/.test(month)) {
            return jsonErr("month=YYYY-MM is required", 400);
        }
        // Widened by a week either side so the grid's leading and trailing
        // days (which belong to the neighbouring months) are not blank.
        var first = month + "-01";
        var y = parseInt(month.slice(0, 4), 10), m = parseInt(month.slice(5, 7), 10);
        var lastDay = new Date(Date.UTC(y, m, 0)).getUTCDate();
        var last = month + "-" + (lastDay < 10 ? "0" + lastDay : lastDay);
        var fromD = new Date(Date.UTC(y, m - 1, 1) - 7 * 86400000).toISOString().slice(0, 10);
        var toD = new Date(Date.UTC(y, m - 1, lastDay) + 7 * 86400000).toISOString().slice(0, 10);

        var rows = await env.DB.prepare(
            "SELECT * FROM gm_events WHERE client_id = ? AND event_date >= ? AND event_date <= ? " +
            "ORDER BY event_date ASC, COALESCE(start_time,'') ASC"
        ).bind(id, fromD, toD).all();

        var own = (rows.results || []).map(gmEventOut);
        var derived = await gmDerivedJobEvents(env, id, fromD, toD);
        var club = await gmClubInviteEvents(env, fromD, toD);
        var apex = await gmApexMeetingEvents(env, id, fromD, toD);

        return jsonOk({
            month: month,
            range: { from: fromD, to: toD, month_start: first, month_end: last },
            events: own.concat(derived).concat(club).concat(apex)
        });
    } catch (e) {
        return jsonErr("Error fetching calendar: " + e.message, 500);
    }
}

async function handlePostGmEvent(id, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }

        var body = await request.json();
        var f = await gmEventFields(env, id, body, false);
        if (f.error) { return jsonErr(f.error, 400); }

        var eventId = crypto.randomUUID();
        await env.DB.prepare(
            "INSERT INTO gm_events (id, client_id, event_type, title, title_overridden, event_date, start_time, end_time, " +
            "all_day, location, description, job_id, lead_id, assigned_to, created_by, updated_by) " +
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        ).bind(
            eventId, id, f.event_type, f.title, f.title_overridden || 0, f.event_date,
            f.start_time || null, f.end_time || null, f.all_day || 0,
            f.location || null, f.description || null,
            f.job_id || null, f.lead_id || null, f.assigned_to || null,
            actorName(user), actorName(user)
        ).run();

        var row = await env.DB.prepare("SELECT * FROM gm_events WHERE id = ?").bind(eventId).first();
        return jsonOk({ event: gmEventOut(row) });
    } catch (e) {
        return jsonErr("Error creating event: " + e.message, 500);
    }
}

async function handlePutGmEvent(id, eventId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }

        var existing = await env.DB.prepare(
            "SELECT id FROM gm_events WHERE id = ? AND client_id = ?"
        ).bind(eventId, id).first();
        if (!existing) { return jsonErr("Event not found", 404); }

        var body = await request.json();
        var f = await gmEventFields(env, id, body, true);
        if (f.error) { return jsonErr(f.error, 400); }

        var cols = ["event_type", "title", "title_overridden", "event_date", "start_time", "end_time",
                    "all_day", "location", "description", "job_id", "lead_id", "assigned_to"];
        var sets = [], binds = [];
        cols.forEach(function (c) {
            if (Object.prototype.hasOwnProperty.call(f, c)) {
                sets.push(c + " = ?"); binds.push(f[c] === undefined ? null : f[c]);
            }
        });
        if (!sets.length) { return jsonErr("Nothing to update", 400); }
        // Stamped from the session, never from the body.
        sets.push("updated_by = ?"); binds.push(actorName(user));
        sets.push("updated_at = datetime('now')");
        binds.push(eventId, id);

        await env.DB.prepare(
            "UPDATE gm_events SET " + sets.join(", ") + " WHERE id = ? AND client_id = ?"
        ).bind(...binds).run();

        var row = await env.DB.prepare("SELECT * FROM gm_events WHERE id = ?").bind(eventId).first();
        return jsonOk({ event: gmEventOut(row) });
    } catch (e) {
        return jsonErr("Error updating event: " + e.message, 500);
    }
}

async function handleDeleteGmEvent(id, eventId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }

        var row = await env.DB.prepare(
            "SELECT id FROM gm_events WHERE id = ? AND client_id = ?"
        ).bind(eventId, id).first();
        if (!row) { return jsonErr("Event not found", 404); }

        await env.DB.prepare("DELETE FROM gm_events WHERE id = ? AND client_id = ?")
            .bind(eventId, id).run();
        return jsonOk({ deleted: true });
    } catch (e) {
        return jsonErr("Error deleting event: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Notes on a lead or a project — gm_notes.
//
// A dated thread with an author, not a text field. gm_leads.observacao is a
// FIELD ON THE LEAD ("observação do trabalho") and is deliberately untouched
// by all of this: see migrations/gm_notes.sql.
//
// created_by / created_at are SERVER-SET from the authenticated session and
// never read from the request body — the client_notes and lead_contact_log
// convention. A caller can send created_by; it is ignored.
//
// Editing and deleting are limited to your OWN note, matched on the same
// actor string the insert stamped. Sellers never reach these routes.
// ---------------------------------------------------------------------------

var GM_NOTE_PARENTS = { lead: "gm_leads", job: "gm_jobs" };

// The parent row must exist AND belong to this client before a note can be
// read or written against it, so a guessed id from another business is a 404
// rather than a thread.
async function gmNoteParentOk(env, clientId, parentType, parentId) {
    var table = GM_NOTE_PARENTS[parentType];
    if (!table) { return false; }
    var row = await env.DB.prepare(
        "SELECT id FROM " + table + " WHERE id = ? AND client_id = ?"
    ).bind(parentId, clientId).first();
    return !!row;
}

// Who the session is, for stamping and for the "is this mine?" check. One
// helper so the insert and the ownership test can never drift apart.
function gmNoteActor(user) {
    return user.display_name || user.email || user.username || user.role || null;
}

function gmNoteOut(row, actor) {
    return {
        id: row.id,
        parent_type: row.parent_type,
        parent_id: row.parent_id,
        body: row.body,
        created_by: row.created_by || null,
        created_at: row.created_at,
        // Drives whether the UI offers edit/delete. The server re-checks on
        // every write regardless — this is a hint, not the enforcement.
        is_mine: !!actor && row.created_by === actor
    };
}

async function handleGetGmNotes(id, parentType, parentId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        if (!GM_NOTE_PARENTS[parentType]) { return jsonErr("Invalid note parent", 400); }
        if (!(await gmNoteParentOk(env, id, parentType, parentId))) {
            return jsonErr("Record not found", 404);
        }
        // Notes hang off leads AND jobs. Only the lead side has a vendedor to
        // check, and a seller has no route to a job note at all (gm/jobs is
        // absent from sellerRequestAllowed), so guarding the lead parent is
        // the complete check for a seller session.
        if (parentType === "lead") {
            var sellerBlock = await gmSellerLeadGuard(env, user, id, parentId);
            if (sellerBlock) { return sellerBlock; }
        }

        // Newest first: a thread is read from the most recent entry.
        var rows = await env.DB.prepare(
            "SELECT * FROM gm_notes WHERE client_id = ? AND parent_type = ? AND parent_id = ? " +
            "ORDER BY created_at DESC, rowid DESC"
        ).bind(id, parentType, parentId).all();

        var actor = gmNoteActor(user);
        return jsonOk({
            notes: (rows.results || []).map(function(r) { return gmNoteOut(r, actor); })
        });
    } catch (e) {
        return jsonErr("Error fetching notes: " + e.message, 500);
    }
}

async function handlePostGmNote(id, parentType, parentId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        if (!GM_NOTE_PARENTS[parentType]) { return jsonErr("Invalid note parent", 400); }
        if (!(await gmNoteParentOk(env, id, parentType, parentId))) {
            return jsonErr("Record not found", 404);
        }
        // Notes hang off leads AND jobs. Only the lead side has a vendedor to
        // check, and a seller has no route to a job note at all (gm/jobs is
        // absent from sellerRequestAllowed), so guarding the lead parent is
        // the complete check for a seller session.
        if (parentType === "lead") {
            var sellerBlock = await gmSellerLeadGuard(env, user, id, parentId);
            if (sellerBlock) { return sellerBlock; }
        }

        var body = await request.json();
        var text = gmStr(body.body, 4000);
        if (!text) { return jsonErr("A nota não pode ficar vazia / Note cannot be empty", 400); }

        var noteId = crypto.randomUUID();
        // created_by comes from the SESSION. Anything the caller sent under
        // that name is discarded here, not sanitised.
        await env.DB.prepare(
            "INSERT INTO gm_notes (id, client_id, parent_type, parent_id, body, created_by) " +
            "VALUES (?, ?, ?, ?, ?, ?)"
        ).bind(noteId, id, parentType, parentId, text, gmNoteActor(user)).run();

        var row = await env.DB.prepare("SELECT * FROM gm_notes WHERE id = ?").bind(noteId).first();
        return jsonOk({ note: gmNoteOut(row, gmNoteActor(user)) });
    } catch (e) {
        return jsonErr("Error saving note: " + e.message, 500);
    }
}

async function handlePutGmNote(id, parentType, parentId, noteId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }

        if (parentType === "lead") {
            var sellerBlock = await gmSellerLeadGuard(env, user, id, parentId);
            if (sellerBlock) { return sellerBlock; }
        }

        var existing = await env.DB.prepare(
            "SELECT * FROM gm_notes WHERE id = ? AND client_id = ? AND parent_type = ? AND parent_id = ?"
        ).bind(noteId, id, parentType, parentId).first();
        if (!existing) { return jsonErr("Note not found", 404); }

        // Your own note only. Enforced server-side, not by hiding a button.
        var actor = gmNoteActor(user);
        if (!actor || existing.created_by !== actor) {
            return jsonErr("You can only edit your own note", 403);
        }

        var body = await request.json();
        var text = gmStr(body.body, 4000);
        if (!text) { return jsonErr("A nota não pode ficar vazia / Note cannot be empty", 400); }

        // Only the body is writable. created_by and created_at are never
        // updated: the author and the time it was written are the record.
        await env.DB.prepare("UPDATE gm_notes SET body = ? WHERE id = ?").bind(text, noteId).run();

        var row = await env.DB.prepare("SELECT * FROM gm_notes WHERE id = ?").bind(noteId).first();
        return jsonOk({ note: gmNoteOut(row, actor) });
    } catch (e) {
        return jsonErr("Error updating note: " + e.message, 500);
    }
}

async function handleDeleteGmNote(id, parentType, parentId, noteId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }

        if (parentType === "lead") {
            var sellerBlock = await gmSellerLeadGuard(env, user, id, parentId);
            if (sellerBlock) { return sellerBlock; }
        }

        var existing = await env.DB.prepare(
            "SELECT * FROM gm_notes WHERE id = ? AND client_id = ? AND parent_type = ? AND parent_id = ?"
        ).bind(noteId, id, parentType, parentId).first();
        if (!existing) { return jsonErr("Note not found", 404); }

        var actor = gmNoteActor(user);
        if (!actor || existing.created_by !== actor) {
            return jsonErr("You can only delete your own note", 403);
        }

        await env.DB.prepare("DELETE FROM gm_notes WHERE id = ?").bind(noteId).run();
        return jsonOk({ deleted: true });
    } catch (e) {
        return jsonErr("Error deleting note: " + e.message, 500);
    }
}

function gmJobFields(body, partial) {
    var out = {};
    function has(k) { return Object.prototype.hasOwnProperty.call(body, k); }
    if (!partial || has("obra")) {
        var obra = gmStr(body.obra, 300);
        if (!obra) { return { error: "CLIENTE / OBRA é obrigatório" }; }
        out.obra = obra;
    }
    if (has("status")) {
        if (GM_JOB_STATUSES.indexOf(body.status) === -1) { return { error: "Status inválido" }; }
        out.status = body.status;
    }
    var numFields = ["valor", "material", "mao_de_obra", "outros"];
    for (var i = 0; i < numFields.length; i++) {
        if (has(numFields[i])) { out[numFields[i]] = gmNum(body[numFields[i]]); }
    }
    var strFields = [["mes_entrega", 40], ["inicio", 40], ["prazo_previsto", 40], ["entrega_real", 40]];
    for (var j = 0; j < strFields.length; j++) {
        var k = strFields[j][0];
        if (has(k)) { out[k] = body[k] === null ? null : gmStr(body[k], strFields[j][1]); }
    }
    return { fields: out };
}

async function handlePostGmJob(id, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        var body = {};
        try { body = await request.json(); } catch (e2) { body = {}; }
        var parsed = gmJobFields(body, false);
        if (parsed.error) { return jsonErr(parsed.error, 400); }
        var f = parsed.fields;
        var rowId = crypto.randomUUID();
        await env.DB.prepare(
            "INSERT INTO gm_jobs (id, client_id, obra, mes_entrega, valor, material, mao_de_obra, outros, inicio, prazo_previsto, entrega_real, status) " +
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        ).bind(rowId, id, f.obra,
            f.mes_entrega !== undefined ? f.mes_entrega : null,
            f.valor !== undefined ? f.valor : null,
            f.material !== undefined ? f.material : null,
            f.mao_de_obra !== undefined ? f.mao_de_obra : null,
            f.outros !== undefined ? f.outros : null,
            f.inicio !== undefined ? f.inicio : null,
            f.prazo_previsto !== undefined ? f.prazo_previsto : null,
            f.entrega_real !== undefined ? f.entrega_real : null,
            f.status !== undefined ? f.status : "Em andamento").run();
        var row = await gmOwnedRow(env, "gm_jobs", rowId, id);
        return jsonOk({ created: true, job: row });
    } catch (e) {
        return jsonErr("Error creating job: " + e.message, 500);
    }
}

async function handlePutGmJob(id, rowId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        var existing = await gmOwnedRow(env, "gm_jobs", rowId, id);
        if (!existing) { return jsonErr("Job not found", 404); }
        var body = {};
        try { body = await request.json(); } catch (e2) { body = {}; }
        var parsed = gmJobFields(body, true);
        if (parsed.error) { return jsonErr(parsed.error, 400); }
        var f = parsed.fields;
        var sets = [], binds = [];
        Object.keys(f).forEach(function(k) { sets.push(k + " = ?"); binds.push(f[k]); });
        if (!sets.length) { return jsonErr("Nothing to update", 400); }
        sets.push("updated_at = datetime('now')");
        binds.push(rowId); binds.push(id);
        await gmRunUpdate(env, "UPDATE gm_jobs SET " + sets.join(", ") + " WHERE id = ? AND client_id = ?", binds);
        var row = await gmOwnedRow(env, "gm_jobs", rowId, id);
        return jsonOk({ saved: true, job: row });
    } catch (e) {
        return jsonErr("Error updating job: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// SALESPERSON LOGIN REQUESTS (gm_seller_login_requests)
//
// A client asking us to give one of their salespeople a portal login. THESE
// ROUTES GRANT NOTHING. They write a queue row that Rafa and Alice work by
// hand. No login is created, client_logins is not touched, and approving a
// request only stamps status/resolved_at/resolved_by. The actual salesperson
// seat — authentication and the scoped, pipeline-only reads described in the
// portal copy — is a separate future build.
//
// Route: POST /api/gm/seller-login-requests   — the client asks. The client_id
//   comes from the authenticated session ONLY; a body-supplied client_id is
//   ignored, so a client can never queue a request against another company.
// Route: GET  /api/gm/seller-login-requests   — admin queue (alice/rafa/dev),
//   optionally filtered to one client with ?client_id= for the client.html card.
// Route: POST /api/gm/seller-login-requests/:id/:decision — admin approve/reject.
// ---------------------------------------------------------------------------

async function handlePostGmSellerLoginRequest(request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }

        var body = await request.json().catch(function() { return {}; });

        // The client_id is the session's, never the body's. An admin acting on
        // a client's behalf may pass one; a client role may not.
        var clientId = user.client_id || null;
        if (isAdminRole(user)) { clientId = gmStr(body.client_id, 80) || clientId; }
        if (!clientId) { return jsonErr("No client context for this request", 400); }

        var sellerName = gmStr(body.seller_name, 80);
        if (!sellerName) { return jsonErr("Nome do vendedor obrigatório / Salesperson name is required", 400); }

        // The name must currently be in the client's own Vendedores list. This
        // keeps the queue tied to a real configured salesperson rather than any
        // arbitrary string a caller invents.
        var config = await gmGetConfig(env, clientId);
        var known = (config.vendedores || []).some(function(v) {
            return String(v).trim().toLowerCase() === sellerName.toLowerCase();
        });
        if (!known) {
            return jsonErr("Vendedor não está na sua lista / Salesperson is not in your list", 400);
        }

        var existing = await env.DB.prepare(
            "SELECT id, status FROM gm_seller_login_requests WHERE client_id = ? AND seller_name = ?"
        ).bind(clientId, sellerName).first();
        // UNIQUE (client_id, seller_name) — a second tap is a no-op, not an error.
        if (existing) { return jsonOk({ requested: true, already: true, status: existing.status }); }

        await env.DB.prepare(
            "INSERT INTO gm_seller_login_requests (id, client_id, seller_name, status, requested_by) " +
            "VALUES (?, ?, ?, 'pending', ?) ON CONFLICT (client_id, seller_name) DO NOTHING"
        ).bind(crypto.randomUUID(), clientId, sellerName, user.username || user.email || "client").run();

        return jsonOk({ requested: true, status: "pending" });
    } catch (e) {
        return jsonErr("Error requesting salesperson login: " + e.message, 500);
    }
}

async function handleGetGmSellerLoginRequests(request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!isAdminRole(user)) { return jsonErr("Forbidden", 403); }

        var filterClient = new URL(request.url).searchParams.get("client_id");
        var sql =
            "SELECT r.id, r.client_id, c.name AS client_name, r.seller_name, r.status, " +
            "r.requested_at, r.requested_by FROM gm_seller_login_requests r " +
            "LEFT JOIN clients c ON c.id = r.client_id WHERE r.status = 'pending'";
        var stmt;
        if (filterClient) {
            stmt = env.DB.prepare(sql + " AND r.client_id = ? ORDER BY r.requested_at ASC").bind(filterClient);
        } else {
            stmt = env.DB.prepare(sql + " ORDER BY r.requested_at ASC");
        }
        var rows = await stmt.all();
        var out = (rows.results || []).map(function(r) {
            return {
                id: r.id, client_id: r.client_id, client_name: r.client_name || r.client_id,
                seller_name: r.seller_name, status: r.status,
                requested_at: r.requested_at, requested_by: r.requested_by
            };
        });
        return jsonOk({ pending: out });
    } catch (e) {
        return jsonErr("Error fetching salesperson login requests: " + e.message, 500);
    }
}

// Approving PROVISIONS A REAL LOGIN: a role='seller' row in client_logins with
// a generated username and a temporary password, returned here exactly once.
// Rejecting stamps status and creates nothing, as it always has.
async function handlePostGmSellerLoginDecision(reqId, decision, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!isAdminRole(user)) { return jsonErr("Forbidden", 403); }
        if (decision !== "approve" && decision !== "reject") { return jsonErr("Invalid decision", 400); }

        var row = await env.DB.prepare(
            "SELECT id, client_id, seller_name, status FROM gm_seller_login_requests WHERE id = ?"
        ).bind(reqId).first();
        if (!row) { return jsonErr("Not found", 404); }

        var status = decision === "approve" ? "approved" : "rejected";
        var credentials = null;

        if (decision === "approve") {
            var client = await env.DB.prepare("SELECT id, name FROM clients WHERE id = ?")
                .bind(row.client_id).first();
            if (!client) { return jsonErr("Client not found", 404); }

            // Re-approving a request that already has a live seat must not mint
            // a second login for the same person — UNIQUE (client_id,
            // seller_name) would reject it anyway, but a clear message beats a
            // constraint error.
            var seat = await env.DB.prepare(
                "SELECT username FROM client_logins WHERE client_id = ? AND role = 'seller' AND seller_name = ?"
            ).bind(row.client_id, row.seller_name).first();
            if (seat) {
                return jsonOk({
                    saved: true, status: "approved", provisioned: false,
                    already: true, username: seat.username
                });
            }

            credentials = await createSellerLogin(
                env, row.client_id, client.name, row.seller_name, actorName(user)
            );
        }

        await env.DB.prepare(
            "UPDATE gm_seller_login_requests SET status = ?, resolved_at = datetime('now'), resolved_by = ? WHERE id = ?"
        ).bind(status, user.username || user.email || "admin", reqId).run();

        // temp_password travels back to the admin UI ONCE. Only its hash was
        // stored, so it is unrecoverable after this response.
        return jsonOk({
            saved: true, status: status,
            provisioned: !!credentials,
            seller_name: row.seller_name,
            username: credentials ? credentials.username : null,
            temp_password: credentials ? credentials.temp_password : null
        });
    } catch (e) {
        return jsonErr("Error resolving salesperson login request: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Route: GET /api/clients/:id/seller-logins — active salesperson seats.
//
// Admin (the client.html profile card) and the client themselves (their own
// Ajustes card, read-only, so an owner knows who can see their pipeline).
// ---------------------------------------------------------------------------

async function handleGetSellerLogins(id, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        // A salesperson does not get the roster of their colleagues.
        if (sessionSellerName(user)) { return jsonErr("Forbidden", 403); }
        var rows = await env.DB.prepare(
            "SELECT username, seller_name, last_login_at, must_change_password, created_at " +
            "FROM client_logins WHERE client_id = ? AND role = 'seller' ORDER BY seller_name"
        ).bind(id).all();
        return jsonOk({ seats: rows.results || [] });
    } catch (e) {
        return jsonErr("Error fetching salesperson logins: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Route: DELETE /api/clients/:id/seller-logins/:username — revoke a seat.
//
// Deletes the login row and its live sessions. Their LEADS ARE NOT TOUCHED:
// gm_leads.vendedor is a plain text name, the rows stay with the business, and
// the work history is preserved. Revoking access is not the same as erasing
// what someone did. Admin only.
// ---------------------------------------------------------------------------

async function handleDeleteSellerLogin(id, username, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!isAdminRole(user)) { return jsonErr("Forbidden", 403); }
        // role='seller' in the WHERE is load-bearing: without it a crafted
        // username could delete the business OWNER's login through this route.
        var seat = await env.DB.prepare(
            "SELECT username, seller_name FROM client_logins WHERE client_id = ? AND username = ? AND role = 'seller'"
        ).bind(id, username).first();
        if (!seat) { return jsonErr("Seat not found", 404); }
        await env.DB.prepare("DELETE FROM client_auth_tokens WHERE username = ?").bind(username).run();
        await env.DB.prepare(
            "DELETE FROM client_logins WHERE client_id = ? AND username = ? AND role = 'seller'"
        ).bind(id, username).run();
        // The request row goes back to a clean slate so the owner can ask
        // again later; leaving it 'approved' would strand the button.
        await env.DB.prepare(
            "DELETE FROM gm_seller_login_requests WHERE client_id = ? AND seller_name = ?"
        ).bind(id, seat.seller_name).run();
        return jsonOk({ revoked: true, username: username });
    } catch (e) {
        return jsonErr("Error revoking salesperson login: " + e.message, 500);
    }
}

// The portal's own read: every request for the caller's client, so the button
// next to each salesperson can show not-requested / pending / approved.
async function handleGetGmSellerLoginRequestsForClient(id, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        var rows = await env.DB.prepare(
            "SELECT seller_name, status, requested_at FROM gm_seller_login_requests WHERE client_id = ?"
        ).bind(id).all();
        return jsonOk({ requests: rows.results || [] });
    } catch (e) {
        return jsonErr("Error fetching salesperson login requests: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Route: DELETE /api/clients/:id/gm/<collection>/:rowId
// FK-referenced rows are protected with a clear message instead of a raw
// constraint error; a deleted lead first releases its base-ouro back-link.
// ---------------------------------------------------------------------------

var GM_DELETE_TABLES = {
    "leads":     "gm_leads",
    "roadmap":   "gm_roadmap",
    "base-ouro": "gm_base_ouro",
    "partners":  "gm_partners",
    "finance":   "gm_finance",
    "jobs":      "gm_jobs"
};

async function handleDeleteGmRow(id, collection, rowId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (!requireClientAccess(user, id)) { return jsonErr("Forbidden", 403); }
        var table = GM_DELETE_TABLES[collection];
        if (!table) { return jsonErr("Not found", 404); }
        var existing = await gmOwnedRow(env, table, rowId, id);
        if (!existing) { return jsonErr("Not found", 404); }
        if (table === "gm_partners") {
            var refLeads = await env.DB.prepare(
                "SELECT COUNT(*) AS c FROM gm_leads WHERE parceiro_id = ?"
            ).bind(rowId).first();
            if (refLeads && refLeads.c > 0) {
                return jsonErr("Este parceiro tem leads vinculados no CRM — remova o vínculo nos leads antes de excluir", 400);
            }
        }
        if (table === "gm_jobs") {
            var refFin = await env.DB.prepare(
                "SELECT COUNT(*) AS c FROM gm_finance WHERE obra_id = ?"
            ).bind(rowId).first();
            if (refFin && refFin.c > 0) {
                return jsonErr("Esta obra tem lançamentos financeiros vinculados — remova o vínculo antes de excluir", 400);
            }
        }
        if (table === "gm_leads") {
            await env.DB.prepare(
                "UPDATE gm_base_ouro SET reactivated_lead_id = NULL WHERE reactivated_lead_id = ?"
            ).bind(rowId).run();
            // Written BEFORE the row goes, and it deliberately OUTLIVES the
            // lead: gm_lead_events has no FK and no cascade, so the record of
            // a deletion survives the thing it describes. Cascading would
            // erase the history at the exact moment the most important event
            // happens, leaving "who deleted the $145,000 lead?" unanswerable.
            //
            // The lead's NAME goes in new_value because once the row is gone
            // an id resolves to nothing, and an orphaned id is not an audit
            // record.
            await gmLogLeadEvents(env, id, rowId, actorName(user), [
                { action: "deleted", field: "cliente",
                  old_value: existing.estagio, new_value: existing.cliente }
            ]);
        }
        await env.DB.prepare("DELETE FROM " + table + " WHERE id = ? AND client_id = ?")
            .bind(rowId, id).run();
        return jsonOk({ deleted: true });
    } catch (e) {
        return jsonErr("Error deleting: " + e.message, 500);
    }
}

// ===========================================================================
// FINANCE-NEW — Plaid-backed budgeting. Parallel to the Zoho finance page,
// which stays live and untouched.
//
// Governing rule for everything below: the dashboard must be useful with ZERO
// input from Alice. No screen may require her to categorize, reconcile or
// confirm before it shows a number. The previous finance tool was correct and
// went completely unused because it demanded exactly that.
// ===========================================================================

// Money is INTEGER CENTS everywhere in this file section. Plaid and Zoho both
// send dollars as floats; convert at the edge, once, and never carry a float
// into a comparison. Math.round (not truncation) so 14.37 -> 1437, not 1436.
function toCents(dollars) {
    var n = Number(dollars);
    if (!isFinite(n)) { return 0; }
    return Math.round(n * 100);
}

function centsToDollars(cents) {
    return (Number(cents) || 0) / 100;
}

// INV- + six zero-padded digits. The INV-2025-0001 shape in
// templates/apex-invoice-data-DRAFT.json is a mockup and is NOT the format.
function formatInvoiceNumber(n) {
    var s = String(n);
    while (s.length < 6) { s = "0" + s; }
    return "INV-" + s;
}

// ---------------------------------------------------------------------------
// Route: POST /api/finance-new/migrate-invoices — alice/rafa/developer only.
//
// One-time (but idempotent) lift of the Zoho Books invoice list into D1.
// Zoho may be dying and these records are the only thing that must survive.
//
// Idempotent on invoices.zoho_invoice_id: re-running updates the existing row
// rather than inserting a second copy, so it is safe to run twice, and safe to
// run again later to pick up a status change made in Zoho.
//
// INV-000016 IS DELIBERATELY SKIPPED. It is a Zoho-auto-generated duplicate of
// Alice's manual INV-000015 (same client, same $1,500, one day apart,
// created_by "Zoho Books" with a recurring profile behind it). It is being
// silently retired -- not imported in any status -- but its NUMBER is burned,
// which is why the counter seeds at 17.
// ---------------------------------------------------------------------------

var ZOHO_SKIP_INVOICE_NUMBERS = ["INV-000016"];

// Zoho 'sent' and 'overdue' both mean "issued and unpaid". Apex never sent
// email through Zoho -- is_emailed is false on every one of them and carries
// no information. Overdue is DERIVED from due_at at render time, never stored,
// so it is not a status here.
function mapZohoInvoiceStatus(zohoStatus) {
    var s = String(zohoStatus || "").toLowerCase();
    if (s === "draft")                      { return "draft"; }
    if (s === "paid")                       { return "paid"; }
    if (s === "void" || s === "voided")     { return "void"; }
    if (s === "sent" || s === "overdue" ||
        s === "unpaid" || s === "viewed" ||
        s === "partially_paid")             { return "sent"; }
    return null;
}

async function handlePostFinanceNewMigrateInvoices(request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (user.role !== "alice" && user.role !== "rafa" && user.role !== "developer") { return jsonErr("Forbidden", 403); }

        var report = {
            zoho_reachable: false,
            zoho_error:     null,
            fetched:        0,
            imported:       0,
            updated:        0,
            skipped:        [],
            unmatched:      [],
            counter_seeded: null
        };

        // Seed the counter FIRST and unconditionally. If Zoho is dead the
        // build must not fail -- Alice still needs to create invoices by hand,
        // and 16 must never be reissued whether or not the lift succeeded.
        await env.DB.prepare(
            "INSERT INTO invoice_counter (id, next_number) VALUES (1, 17) ON CONFLICT(id) DO NOTHING"
        ).run();
        var counterRow = await env.DB.prepare("SELECT next_number FROM invoice_counter WHERE id = 1").first();
        report.counter_seeded = counterRow ? counterRow.next_number : null;

        var zohoAuth;
        try {
            zohoAuth = await getZohoAccessToken(env);
        } catch (e) {
            report.zoho_error = e.message;
            return jsonOk(report);
        }

        // Page through the full invoice list. 200 is Zoho's per_page ceiling.
        var zohoInvoices = [];
        var page = 1;
        while (page <= 20) {
            var listRes = await zohoBankingFetch(
                zohoAuth, "GET",
                "invoices?per_page=200&page=" + page + "&sort_column=invoice_number"
            );
            if (!listRes.ok) {
                report.zoho_error = "Zoho invoice list failed (HTTP " + listRes.status + "): " +
                    ((listRes.data && listRes.data.message) || "unknown");
                return jsonOk(report);
            }
            var batch = (listRes.data && listRes.data.invoices) || [];
            zohoInvoices = zohoInvoices.concat(batch);
            var ctx = listRes.data && listRes.data.page_context;
            if (!ctx || !ctx.has_more_page) { break; }
            page++;
        }

        report.zoho_reachable = true;
        report.fetched = zohoInvoices.length;

        // Resolve Zoho customer -> local client once, up front.
        var clientRes = await env.DB.prepare(
            "SELECT id, name, zoho_customer_id FROM clients WHERE zoho_customer_id IS NOT NULL AND zoho_customer_id != ''"
        ).all();
        var clientByZohoId = {};
        var i;
        for (i = 0; i < clientRes.results.length; i++) {
            clientByZohoId[String(clientRes.results[i].zoho_customer_id)] = clientRes.results[i];
        }

        for (i = 0; i < zohoInvoices.length; i++) {
            var zi = zohoInvoices[i];
            var number = zi.invoice_number;

            if (ZOHO_SKIP_INVOICE_NUMBERS.indexOf(number) !== -1) {
                report.skipped.push({
                    number: number,
                    reason: "Zoho-auto-generated duplicate of INV-000015; retired, number burned"
                });
                continue;
            }

            var status = mapZohoInvoiceStatus(zi.status);
            if (!status) {
                report.skipped.push({ number: number, reason: "unmapped Zoho status '" + zi.status + "'" });
                continue;
            }

            var localClient = clientByZohoId[String(zi.customer_id)] || null;
            if (!localClient) {
                report.unmatched.push({ number: number, zoho_customer: zi.customer_name });
            }

            // issued_date is blank on drafts; fall back to the invoice date.
            var issuedAt = zi.issued_date || zi.date || null;

            var existing = await env.DB.prepare(
                "SELECT id FROM invoices WHERE zoho_invoice_id = ?"
            ).bind(String(zi.invoice_id)).first();

            if (existing) {
                await env.DB.prepare(
                    "UPDATE invoices SET client_id = ?, number = ?, amount_cents = ?, issued_at = ?, " +
                    "due_at = ?, status = ?, source = 'zoho_migrated' WHERE id = ?"
                ).bind(
                    localClient ? localClient.id : null,
                    number,
                    toCents(zi.total),
                    issuedAt,
                    zi.due_date || null,
                    status,
                    existing.id
                ).run();
                report.updated++;
            } else {
                await env.DB.prepare(
                    "INSERT INTO invoices (id, client_id, number, amount_cents, issued_at, due_at, status, " +
                    "zoho_invoice_id, source) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'zoho_migrated')"
                ).bind(
                    crypto.randomUUID(),
                    localClient ? localClient.id : null,
                    number,
                    toCents(zi.total),
                    issuedAt,
                    zi.due_date || null,
                    status,
                    String(zi.invoice_id)
                ).run();
                report.imported++;
            }
        }

        // The counter must clear every number that now exists, including any
        // Alice added in Zoho after this code was written.
        var maxRow = await env.DB.prepare(
            "SELECT MAX(CAST(REPLACE(number, 'INV-', '') AS INTEGER)) AS max_n FROM invoices WHERE number LIKE 'INV-%'"
        ).first();
        var maxUsed = (maxRow && maxRow.max_n) || 0;
        // 16 is burned even though it was never imported.
        if (maxUsed < 16) { maxUsed = 16; }
        await env.DB.prepare(
            "UPDATE invoice_counter SET next_number = ? WHERE id = 1 AND next_number <= ?"
        ).bind(maxUsed + 1, maxUsed).run();
        var finalCounter = await env.DB.prepare("SELECT next_number FROM invoice_counter WHERE id = 1").first();
        report.counter_seeded = finalCounter ? finalCounter.next_number : null;

        return jsonOk(report);
    } catch (e) {
        return jsonErr("Error migrating invoices: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Plaid HTTP plumbing.
//
// PLAID_CLIENT_ID / PLAID_SECRET / PLAID_ENV are Worker SECRETS. They are read
// from env here and nowhere else, never hardcoded, and never returned to the
// browser. The same goes for the per-Item access_token: it lives in
// plaid_items.access_token, is used only inside this Worker, and is never
// logged or serialized into any response.
// ---------------------------------------------------------------------------

function plaidBaseUrl(env) {
    return "https://" + (env.PLAID_ENV || "production") + ".plaid.com";
}

async function plaidFetch(env, endpoint, body) {
    var payload = Object.assign({}, body, {
        client_id: env.PLAID_CLIENT_ID,
        secret:    env.PLAID_SECRET
    });
    var ctrl  = new AbortController();
    var timer = setTimeout(function() { ctrl.abort(); }, 20000);
    var res;
    try {
        res = await fetch(plaidBaseUrl(env) + endpoint, {
            method:  "POST",
            headers: { "Content-Type": "application/json" },
            body:    JSON.stringify(payload),
            signal:  ctrl.signal
        });
    } finally {
        clearTimeout(timer);
    }
    var data = await res.json();
    return { ok: res.ok, status: res.status, data: data };
}

// Plaid error surfaced to the UI WITHOUT echoing the request payload, which
// would carry client_id/secret into a log or a browser console.
function plaidErrMessage(result) {
    var d = result && result.data;
    if (!d) { return "Plaid request failed (HTTP " + (result && result.status) + ")"; }
    return (d.error_message || d.error_code || "Plaid request failed") +
           (d.error_code ? " [" + d.error_code + "]" : "");
}

function isValidPurpose(p) {
    return p === "business" || p === "personal";
}

// ---------------------------------------------------------------------------
// Route: POST /api/finance-new/link-token — alice/rafa/developer only.
// Body: { purpose: 'business' | 'personal' }
//
// purpose is carried through the whole link flow from the BUTTON Alice
// clicked, and is echoed back so the client can hand it to /exchange. It is
// never derived from the institution or the bank's account names.
// ---------------------------------------------------------------------------

async function handlePostFinanceNewLinkToken(request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (user.role !== "alice" && user.role !== "rafa" && user.role !== "developer") { return jsonErr("Forbidden", 403); }

        var body = await request.json().catch(function() { return {}; });
        var purpose = body.purpose;
        if (!isValidPurpose(purpose)) {
            return jsonErr("purpose must be 'business' or 'personal'", 400);
        }

        var result = await plaidFetch(env, "/link/token/create", {
            user:          { client_user_id: "apex-" + (user.email || "admin") },
            client_name:   "Apex Command Center",
            products:      ["transactions"],
            country_codes: ["US"],
            language:      "pt"
        });

        // Plaid rejects unsupported Link languages outright. Portuguese is not
        // available in every account/region combination, so fall back to
        // English rather than leaving Alice with a dead button.
        if (!result.ok && result.data && result.data.error_code === "INVALID_FIELD") {
            result = await plaidFetch(env, "/link/token/create", {
                user:          { client_user_id: "apex-" + (user.email || "admin") },
                client_name:   "Apex Command Center",
                products:      ["transactions"],
                country_codes: ["US"],
                language:      "en"
            });
        }

        if (!result.ok) { return jsonErr(plaidErrMessage(result), 502); }
        return jsonOk({ link_token: result.data.link_token, purpose: purpose });
    } catch (e) {
        return jsonErr("Error creating link token: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Route: POST /api/finance-new/link-token/update — alice/rafa/developer only.
// Body: { item_id }
//
// Update mode re-auth: an existing Item whose consent lapsed or whose login
// broke. Takes access_token and an EMPTY products array -- passing products
// here is what makes Plaid reject an update-mode token.
// ---------------------------------------------------------------------------

async function handlePostFinanceNewLinkTokenUpdate(request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (user.role !== "alice" && user.role !== "rafa" && user.role !== "developer") { return jsonErr("Forbidden", 403); }

        var body = await request.json().catch(function() { return {}; });
        if (!body.item_id) { return jsonErr("item_id required", 400); }

        var item = await env.DB.prepare(
            "SELECT id, access_token FROM plaid_items WHERE id = ? OR plaid_item_id = ?"
        ).bind(body.item_id, body.item_id).first();
        if (!item) { return jsonErr("Item not found", 404); }

        var result = await plaidFetch(env, "/link/token/create", {
            user:          { client_user_id: "apex-" + (user.email || "admin") },
            client_name:   "Apex Command Center",
            products:      [],
            country_codes: ["US"],
            language:      "en",
            access_token:  item.access_token
        });

        if (!result.ok) { return jsonErr(plaidErrMessage(result), 502); }
        return jsonOk({ link_token: result.data.link_token });
    } catch (e) {
        return jsonErr("Error creating update link token: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Route: POST /api/finance-new/exchange — alice/rafa/developer only.
// Body: { public_token, purpose, accounts: [{ id, purpose? }] }
//
// Exchanges the public token, stores the Item, and creates one `accounts` row
// per account the bank returned.
//
// PER-ACCOUNT PURPOSE: both Apex accounts sit at BofA and may arrive under a
// single Item on one login. When that happens the top-level `purpose` is only
// a default -- accounts[].purpose overrides it per account, so Alice can tag
// checking as business and savings as personal in the same link. Nothing is
// inferred from account.name or .subtype.
// ---------------------------------------------------------------------------

async function handlePostFinanceNewExchange(request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (user.role !== "alice" && user.role !== "rafa" && user.role !== "developer") { return jsonErr("Forbidden", 403); }

        var body = await request.json().catch(function() { return {}; });
        if (!body.public_token) { return jsonErr("public_token required", 400); }
        var defaultPurpose = body.purpose;
        if (!isValidPurpose(defaultPurpose)) {
            return jsonErr("purpose must be 'business' or 'personal'", 400);
        }

        var exch = await plaidFetch(env, "/item/public_token/exchange", {
            public_token: body.public_token
        });
        if (!exch.ok) { return jsonErr(plaidErrMessage(exch), 502); }

        var accessToken = exch.data.access_token;
        var plaidItemId = exch.data.item_id;

        // Institution name for the UI. Non-fatal if it fails.
        var institution = null;
        var itemRes = await plaidFetch(env, "/item/get", { access_token: accessToken });
        if (itemRes.ok && itemRes.data.item && itemRes.data.item.institution_id) {
            var instRes = await plaidFetch(env, "/institutions/get_by_id", {
                institution_id: itemRes.data.item.institution_id,
                country_codes:  ["US"]
            });
            if (instRes.ok && instRes.data.institution) {
                institution = instRes.data.institution.name;
            }
        }

        var existingItem = await env.DB.prepare(
            "SELECT id FROM plaid_items WHERE plaid_item_id = ?"
        ).bind(plaidItemId).first();
        var itemRowId;
        if (existingItem) {
            itemRowId = existingItem.id;
            // Re-link of a known Item: refresh the credential and clear any
            // reauth flag, but keep the cursor so sync resumes where it left off.
            await env.DB.prepare(
                "UPDATE plaid_items SET access_token = ?, institution = ?, status = 'good' WHERE id = ?"
            ).bind(accessToken, institution, itemRowId).run();
        } else {
            itemRowId = crypto.randomUUID();
            await env.DB.prepare(
                "INSERT INTO plaid_items (id, plaid_item_id, access_token, institution, status) " +
                "VALUES (?, ?, ?, ?, 'good')"
            ).bind(itemRowId, plaidItemId, accessToken, institution).run();
        }

        // Per-account purpose overrides sent by the tagging step.
        var purposeByAccount = {};
        if (Array.isArray(body.accounts)) {
            for (var a = 0; a < body.accounts.length; a++) {
                var sel = body.accounts[a];
                if (sel && sel.id && isValidPurpose(sel.purpose)) {
                    purposeByAccount[sel.id] = sel.purpose;
                }
            }
        }

        var acctRes = await plaidFetch(env, "/accounts/get", { access_token: accessToken });
        if (!acctRes.ok) { return jsonErr(plaidErrMessage(acctRes), 502); }

        var created = [];
        var accts = acctRes.data.accounts || [];
        for (var i = 0; i < accts.length; i++) {
            var acc = accts[i];
            var purpose = purposeByAccount[acc.account_id] || defaultPurpose;
            var balances = acc.balances || {};
            var existingAcct = await env.DB.prepare(
                "SELECT id FROM accounts WHERE plaid_account_id = ?"
            ).bind(acc.account_id).first();

            if (existingAcct) {
                await env.DB.prepare(
                    "UPDATE accounts SET plaid_item_id = ?, institution = ?, name = ?, mask = ?, subtype = ?, " +
                    "purpose = ?, balance_cents = ?, available_cents = ?, last_synced_at = datetime('now'), " +
                    "status = 'active' WHERE id = ?"
                ).bind(
                    plaidItemId, institution, acc.name, acc.mask, acc.subtype, purpose,
                    balances.current === null || balances.current === undefined ? null : toCents(balances.current),
                    balances.available === null || balances.available === undefined ? null : toCents(balances.available),
                    existingAcct.id
                ).run();
                created.push({ id: existingAcct.id, name: acc.name, mask: acc.mask, purpose: purpose });
            } else {
                var newId = crypto.randomUUID();
                await env.DB.prepare(
                    "INSERT INTO accounts (id, plaid_item_id, plaid_account_id, institution, name, mask, subtype, " +
                    "purpose, balance_cents, available_cents, last_synced_at) " +
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))"
                ).bind(
                    newId, plaidItemId, acc.account_id, institution, acc.name, acc.mask, acc.subtype, purpose,
                    balances.current === null || balances.current === undefined ? null : toCents(balances.current),
                    balances.available === null || balances.available === undefined ? null : toCents(balances.available)
                ).run();
                created.push({ id: newId, name: acc.name, mask: acc.mask, purpose: purpose });
            }
        }

        // access_token is deliberately NOT part of this response.
        return jsonOk({ item_id: itemRowId, institution: institution, accounts: created });
    } catch (e) {
        return jsonErr("Error exchanging public token: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Route: GET /api/finance-new/accounts — alice/rafa/developer only.
// Lists linked accounts plus the health of the Item behind each, so the page
// can raise a re-auth banner without a second round trip.
// ---------------------------------------------------------------------------

async function handleGetFinanceNewAccounts(request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (user.role !== "alice" && user.role !== "rafa" && user.role !== "developer") { return jsonErr("Forbidden", 403); }

        var res = await env.DB.prepare(
            "SELECT a.id, a.plaid_item_id, a.institution, a.name, a.mask, a.subtype, a.purpose, " +
            "a.balance_cents, a.available_cents, a.last_synced_at, a.status, " +
            "i.id AS item_row_id, i.status AS item_status, i.last_synced_at AS item_last_synced_at " +
            "FROM accounts a LEFT JOIN plaid_items i ON i.plaid_item_id = a.plaid_item_id " +
            "WHERE a.status = 'active' ORDER BY a.purpose ASC, a.name ASC"
        ).all();

        var needsReauth = await env.DB.prepare(
            "SELECT id, institution FROM plaid_items WHERE status = 'reauth_required'"
        ).all();

        return jsonOk({ accounts: res.results, reauth_items: needsReauth.results });
    } catch (e) {
        return jsonErr("Error fetching accounts: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Route: PATCH /api/finance-new/accounts/:id — alice/rafa/developer only.
// Body: { purpose }
//
// Correcting a mis-tag WITHOUT unlinking. A wrong tag silently files
// household spending under the business column, so this has to be a one-click
// fix on the dashboard, not a re-link.
// ---------------------------------------------------------------------------

async function handlePatchFinanceNewAccount(accountId, request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (user.role !== "alice" && user.role !== "rafa" && user.role !== "developer") { return jsonErr("Forbidden", 403); }

        var body = await request.json().catch(function() { return {}; });
        if (!isValidPurpose(body.purpose)) {
            return jsonErr("purpose must be 'business' or 'personal'", 400);
        }

        var existing = await env.DB.prepare("SELECT id FROM accounts WHERE id = ?").bind(accountId).first();
        if (!existing) { return jsonErr("Account not found", 404); }

        await env.DB.prepare("UPDATE accounts SET purpose = ? WHERE id = ?")
            .bind(body.purpose, accountId).run();
        return jsonOk({ id: accountId, purpose: body.purpose });
    } catch (e) {
        return jsonErr("Error updating account: " + e.message, 500);
    }
}

// ---------------------------------------------------------------------------
// Plaid transaction sync.
//
// History starts at 2026-07-01 on first sync. /transactions/sync always
// replays from the beginning of available history when called with no cursor,
// so the floor is applied on insert rather than in the request.
// ---------------------------------------------------------------------------

var PLAID_HISTORY_FLOOR = "2026-07-01";

// The free-text note the sender typed on a Zelle payment: for "Livros Apex
// Club", for "GESTAO APEX". It carries real meaning -- which client, which
// event -- so it is stored on its own column rather than discarded. It must
// NOT feed the merchant key, or payments from one client split by whatever
// each of them happened to type in the note field.
function extractMemo(desc) {
    var m = String(desc || "").match(/\bfor\s+"([^"]+)"/i);
    return m ? m[1].trim().slice(0, 120) : null;
}

// Strip the noise BofA puts around a merchant so the composite dedup key and
// the transfer heuristics compare like with like: card suffixes, store
// numbers, dates, and reference ids all vary between the pending and posted
// version of the SAME transaction.
//
// ORDER MATTERS. A Zelle confirmation ref is alphanumeric with single digits
// (ryew3bbnx), so it survives the 4+ digit strip, and the non-alpha pass then
// shatters it into surviving letter chunks (CONF RYEW BBNX). Since the ref is
// unique per transaction, that made EVERY Zelle row its own merchant -- 70
// rows, 69 keys -- so categorization rules matched exactly one row and never
// compounded. The ref and the quoted memo are removed BEFORE that pass.
function normalizeMerchant(desc) {
    var s = String(desc || "");

    s = s.replace(/\bfor\s+"[^"]*"/gi, " ");
    // Both orders BofA emits the ref in:
    //   "Zelle payment to Alice Corsino Conf# ryew3bbnx"        (trailing)
    //   "Zelle Transfer CONF# LCWB7A9V7; ALICE CORSINO"         (name last)
    s = s.replace(/\bCONF#?\s*[A-Z0-9]+;?/gi, " ");

    s = s.toUpperCase();
    s = s.replace(/[0-9]{4,}/g, " ");
    s = s.replace(/[^A-Z ]+/g, " ");
    s = s.replace(/\b(PURCHASE|POS|DEBIT|CREDIT|CARD|XXXX|REF|ID|CKCD|DES|INDN|CO)\b/g, " ");
    s = s.replace(/\s+/g, " ").trim();
    return s.slice(0, 60);
}

function daysBetween(aIso, bIso) {
    var a = Date.parse(String(aIso) + "T00:00:00Z");
    var b = Date.parse(String(bIso) + "T00:00:00Z");
    if (isNaN(a) || isNaN(b)) { return 999; }
    return Math.abs(a - b) / 86400000;
}

// SIGNED age of a deposit relative to an invoice: positive = the deposit came
// after the invoice, negative = BEFORE it existed.
//
// daysBetween() is absolute, which made "30 days early" look identical to
// "30 days late" to the matcher. A real consequence: a $1,500 Zelle from DINIZ
// on Jul 1 was offered as payment for Gator's INV-000015, issued Jul 30 —
// money that arrived a month before the invoice existed, proposed against it
// and swept into "Approve all". Nobody can pay an invoice that does not exist
// yet; a deposit predating one is not a candidate for it.
function depositAgeDays(invoiceAnchorIso, depositDateIso) {
    var a = Date.parse(String(invoiceAnchorIso) + "T00:00:00Z");
    var b = Date.parse(String(depositDateIso) + "T00:00:00Z");
    if (isNaN(a) || isNaN(b)) { return 999; }
    return Math.round((b - a) / 86400000);
}

// Find a row that is ALREADY this transaction, arriving under a new identity.
//
// Plaid re-issues transaction_id when a transaction settles from pending to
// posted, so a plain plaid_transaction_id lookup misses the pending row and
// inserts a duplicate -- every settling transaction counted twice, in both
// the money-out total and the balance-derived views. Two guards:
//   1. pending_transaction_id, which Plaid supplies on the posted record and
//      which points at the id the pending row was stored under.
//   2. a composite of exact amount + normalized merchant + date within 3 days,
//      for feeds that drop that link.
async function findExistingTransaction(env, accountRowId, plaidTxn, amountCents, merchantNorm) {
    var byPendingId = null;
    if (plaidTxn.pending_transaction_id) {
        byPendingId = await env.DB.prepare(
            "SELECT id, date FROM transactions WHERE plaid_transaction_id = ? OR pending_plaid_transaction_id = ?"
        ).bind(plaidTxn.pending_transaction_id, plaidTxn.pending_transaction_id).first();
        if (byPendingId) { return byPendingId; }
    }

    var candidates = await env.DB.prepare(
        "SELECT id, date FROM transactions WHERE account_id = ? AND amount_cents = ? AND merchant_normalized = ? " +
        "AND date >= date(?, '-3 day') AND date <= date(?, '+3 day')"
    ).bind(accountRowId, amountCents, merchantNorm, plaidTxn.date, plaidTxn.date).all();

    if (candidates.results && candidates.results.length === 1) {
        return candidates.results[0];
    }
    return null;
}

async function syncPlaidTransactions(env) {
    var items = await env.DB.prepare(
        "SELECT id, plaid_item_id, access_token, cursor FROM plaid_items WHERE status != 'revoked'"
    ).all();

    var summary = { items: 0, added: 0, modified: 0, removed: 0, errors: [] };

    for (var i = 0; i < items.results.length; i++) {
        var item = items.results[i];
        summary.items++;

        var accountRows = await env.DB.prepare(
            "SELECT id, plaid_account_id FROM accounts WHERE plaid_item_id = ?"
        ).bind(item.plaid_item_id).all();
        var acctIdByPlaid = {};
        var r;
        for (r = 0; r < accountRows.results.length; r++) {
            acctIdByPlaid[accountRows.results[r].plaid_account_id] = accountRows.results[r].id;
        }

        var cursor = item.cursor || null;
        var hasMore = true;
        var guard = 0;

        while (hasMore && guard < 30) {
            guard++;
            var body = { access_token: item.access_token };
            if (cursor) { body.cursor = cursor; }

            var res = await plaidFetch(env, "/transactions/sync", body);

            if (!res.ok) {
                var code = res.data && res.data.error_code;
                // ITEM_LOGIN_REQUIRED means the bank revoked consent or the
                // password changed. Flag it so the page can raise the re-auth
                // banner instead of quietly serving frozen numbers.
                if (code === "ITEM_LOGIN_REQUIRED" || code === "ITEM_ERROR") {
                    await env.DB.prepare(
                        "UPDATE plaid_items SET status = 'reauth_required' WHERE id = ?"
                    ).bind(item.id).run();
                }
                // A cursor Plaid no longer recognizes: restart this Item's
                // history rather than wedging forever on a bad cursor.
                if (code === "TRANSACTIONS_SYNC_MUTATION_DURING_PAGINATION" || code === "INVALID_FIELD") {
                    await env.DB.prepare("UPDATE plaid_items SET cursor = NULL WHERE id = ?").bind(item.id).run();
                }
                summary.errors.push((item.plaid_item_id || item.id) + ": " + (code || "unknown"));
                break;
            }

            var data = res.data;
            var added    = data.added    || [];
            var modified = data.modified || [];
            var removed  = data.removed  || [];
            var t, txn, acctRowId, amountCents, merchNorm;

            // added + modified take the same upsert path: `modified` is how a
            // pending row becomes posted, which is exactly the case dedup exists for.
            var upserts = added.concat(modified);
            for (t = 0; t < upserts.length; t++) {
                txn = upserts[t];
                if (String(txn.date) < PLAID_HISTORY_FLOOR) { continue; }

                acctRowId = acctIdByPlaid[txn.account_id];
                if (!acctRowId) { continue; }   // account not tagged/linked here

                // Plaid sends POSITIVE for money leaving the account. Flip once,
                // here, so every downstream reader sees the natural sign.
                amountCents = -toCents(txn.amount);
                merchNorm   = normalizeMerchant(txn.merchant_name || txn.name);
                // The memo only ever appears in the raw description Plaid puts
                // in .name -- merchant_name, when present, is already cleaned.
                var memoText = extractMemo(txn.name);

                var existing = await findExistingTransaction(env, acctRowId, txn, amountCents, merchNorm);

                if (existing) {
                    await env.DB.prepare(
                        "UPDATE transactions SET plaid_transaction_id = ?, pending_plaid_transaction_id = ?, " +
                        "amount_cents = ?, date = ?, posted_date = ?, description = ?, merchant_normalized = ?, " +
                        "memo = ?, pending = ?, raw_json = ? WHERE id = ?"
                    ).bind(
                        txn.transaction_id,
                        txn.pending_transaction_id || null,
                        amountCents,
                        txn.date,
                        txn.pending ? null : (txn.authorized_date || txn.date),
                        txn.name || null,
                        merchNorm,
                        memoText,
                        txn.pending ? 1 : 0,
                        JSON.stringify(txn),
                        existing.id
                    ).run();
                    summary.modified++;
                } else {
                    await env.DB.prepare(
                        "INSERT INTO transactions (id, account_id, plaid_transaction_id, pending_plaid_transaction_id, " +
                        "amount_cents, date, posted_date, description, merchant_normalized, memo, pending, raw_json) " +
                        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) " +
                        "ON CONFLICT(plaid_transaction_id) DO NOTHING"
                    ).bind(
                        crypto.randomUUID(),
                        acctRowId,
                        txn.transaction_id,
                        txn.pending_transaction_id || null,
                        amountCents,
                        txn.date,
                        txn.pending ? null : (txn.authorized_date || txn.date),
                        txn.name || null,
                        merchNorm,
                        memoText,
                        txn.pending ? 1 : 0,
                        JSON.stringify(txn)
                    ).run();
                    summary.added++;
                }
            }

            for (t = 0; t < removed.length; t++) {
                await env.DB.prepare("DELETE FROM transactions WHERE plaid_transaction_id = ?")
                    .bind(removed[t].transaction_id).run();
                summary.removed++;
            }

            cursor  = data.next_cursor;
            hasMore = !!data.has_more;

            await env.DB.prepare(
                "UPDATE plaid_items SET cursor = ?, last_synced_at = datetime('now'), status = 'good' WHERE id = ?"
            ).bind(cursor, item.id).run();
        }

        // Refresh balances so the headline cards do not drift from the bank.
        var balRes = await plaidFetch(env, "/accounts/balance/get", { access_token: item.access_token });
        if (balRes.ok && balRes.data.accounts) {
            for (r = 0; r < balRes.data.accounts.length; r++) {
                var b = balRes.data.accounts[r];
                var bal = b.balances || {};
                await env.DB.prepare(
                    "UPDATE accounts SET balance_cents = ?, available_cents = ?, last_synced_at = datetime('now') " +
                    "WHERE plaid_account_id = ?"
                ).bind(
                    bal.current === null || bal.current === undefined ? null : toCents(bal.current),
                    bal.available === null || bal.available === undefined ? null : toCents(bal.available),
                    b.account_id
                ).run();
            }
        }
    }

    await detectTransfers(env);

    // Categorize on arrival, using rules only. This is what makes the work
    // shrink: once she has told the system what HOME DEPOT is, every future
    // Home Depot charge is filed before she ever looks at it. Rules are free
    // and deterministic, so this costs nothing and cannot surprise her.
    //
    // The LLM layer is deliberately NOT run here -- it is a paid call and
    // belongs behind an explicit action, not inside a sync that also fires on
    // a 4-hourly cron. Failure is swallowed for the same reason categorization
    // never gates anything: a sync that pulled her transactions correctly must
    // not report failure because an enrichment pass had a problem.
    try {
        await applyCategorizationRules(env, null);
    } catch (e) {
        // Uncategorized is a normal state. Nothing to report.
    }

    return summary;
}

// ---------------------------------------------------------------------------
// Transfer detection — the highest-risk piece in this build.
//
// Moving $1,000 from business to personal is neither income nor expense, but
// it lands as a debit in one account and a credit in the other. Left alone it
// inflates money-in AND money-out, while net stays accidentally correct --
// which is the dangerous part, because the error is invisible in the one
// number that looks right.
//
// Rule: exact amount_cents match, opposite signs, 0-2 calendar day window,
// and a description that looks like a transfer. Both Apex accounts are at
// BofA and both are synced, so both legs should be present.
//
// Detected pairs are marked 'suspected', NOT excluded. Silent exclusion risks
// hiding real income; per-transaction confirmation reintroduces the chore that
// killed the last tool. She confirms once per pair, or once forever.
// ---------------------------------------------------------------------------

var TRANSFER_PATTERNS = /(TRANSFER|ONLINE TRANSFER|ZELLE|WIRE|MOVE MONEY|XFER)/i;

// Does either leg look like a transfer? An account's own last-four appearing
// in the other leg's description counts too -- BofA writes "TO CHK 1234".
function looksLikeTransfer(descA, descB, masks) {
    var a = String(descA || "");
    var b = String(descB || "");
    if (TRANSFER_PATTERNS.test(a) || TRANSFER_PATTERNS.test(b)) { return true; }
    for (var i = 0; i < masks.length; i++) {
        if (!masks[i]) { continue; }
        if (a.indexOf(masks[i]) !== -1 || b.indexOf(masks[i]) !== -1) { return true; }
    }
    return false;
}

async function detectTransfers(env) {
    // Only look at rows not already settled by a human decision. 'confirmed'
    // and 'rejected' are Alice's calls and are never revisited automatically.
    var rows = await env.DB.prepare(
        "SELECT t.id, t.account_id, t.amount_cents, t.date, t.description, t.transfer_status, a.mask " +
        "FROM transactions t JOIN accounts a ON a.id = t.account_id " +
        "WHERE t.transfer_status = 'none' AND t.date >= date('now', '-120 day')"
    ).all();

    var txns = rows.results || [];
    var masks = [];
    var m;
    for (m = 0; m < txns.length; m++) {
        if (txns[m].mask && masks.indexOf(txns[m].mask) === -1) { masks.push(txns[m].mask); }
    }

    var used = {};
    var i, j;
    for (i = 0; i < txns.length; i++) {
        var a = txns[i];
        if (used[a.id]) { continue; }
        if (a.amount_cents >= 0) { continue; }   // anchor on the outflow leg

        for (j = 0; j < txns.length; j++) {
            var b = txns[j];
            if (i === j || used[b.id] || used[a.id]) { continue; }
            if (b.account_id === a.account_id) { continue; }
            if (b.amount_cents !== -a.amount_cents) { continue; }   // exact, opposite
            if (daysBetween(a.date, b.date) > 2) { continue; }
            if (!looksLikeTransfer(a.description, b.description, masks)) { continue; }

            var pairId = crypto.randomUUID();
            await env.DB.prepare(
                "UPDATE transactions SET transfer_status = 'suspected', transfer_pair_id = ? WHERE id IN (?, ?)"
            ).bind(pairId, a.id, b.id).run();
            used[a.id] = true;
            used[b.id] = true;
            break;
        }
    }

    await applyTransferRules(env);
}

// "Always treat this pair as a transfer": a confirmed rule auto-confirms
// future pairs with the same normalized description, so a monthly
// owner's-draw transfer is answered once rather than every month.
async function applyTransferRules(env) {
    var rules = await env.DB.prepare(
        "SELECT pattern FROM categorization_rules WHERE source = 'auto' AND category_id = 'transfer'"
    ).all();
    for (var i = 0; i < rules.results.length; i++) {
        await env.DB.prepare(
            "UPDATE transactions SET transfer_status = 'confirmed', is_transfer = 1 " +
            "WHERE transfer_status = 'suspected' AND merchant_normalized = ?"
        ).bind(rules.results[i].pattern).run();
    }
}

// ---------------------------------------------------------------------------
// Route: GET /api/finance-new/summary — alice/rafa/developer only.
//
// This month's in / out / net per purpose, computed off the raw feed. It
// requires NO categorization and returns numbers the moment transactions land.
//
// THE HONESTY THRESHOLD. Detection rate = detected transfer legs / candidate
// legs, where a candidate is any transaction whose exact amount also appears
// with the opposite sign in another account inside the window -- i.e. the
// things that COULD be transfers.
//   >= 80%    -> show net normally
//   50-80%    -> show net labeled "after detected transfers", raw in/out beside it
//   <  50%    -> do NOT show net at all; show only the two raw numbers
//   unknown   -> too few candidates to measure; treated exactly like < 50%
// A wrong headline she cannot audit is worse than a missing one.
// ---------------------------------------------------------------------------

async function computeTransferDetectionRate(env, sinceDate) {
    // Candidate legs: exact amount present with the opposite sign in a
    // DIFFERENT account within 2 days. This is the same shape as detection
    // minus the description test, so the ratio measures how much of the
    // plausible-transfer population the description rule actually caught.
    var rows = await env.DB.prepare(
        "SELECT id, account_id, amount_cents, date, transfer_status FROM transactions WHERE date >= ?"
    ).bind(sinceDate).all();

    var txns = rows.results || [];
    var candidates = 0;
    var detected = 0;
    var i, j;

    for (i = 0; i < txns.length; i++) {
        var a = txns[i];
        var isCandidate = false;
        for (j = 0; j < txns.length; j++) {
            var b = txns[j];
            if (a.id === b.id) { continue; }
            if (b.account_id === a.account_id) { continue; }
            if (b.amount_cents !== -a.amount_cents) { continue; }
            if (daysBetween(a.date, b.date) > 2) { continue; }
            isCandidate = true;
            break;
        }
        if (!isCandidate) { continue; }
        candidates++;
        if (a.transfer_status === "suspected" || a.transfer_status === "confirmed") { detected++; }
    }

    // ZERO CANDIDATES IS ZERO INFORMATION, NOT PERFECT DETECTION.
    //
    // This used to return rate 1 when candidates === 0, so an empty account
    // displayed a confident green net of $0.00. Harmless while empty, wrong the
    // moment the first sync lands a handful of transactions with no detectable
    // pairs: the rate reads 1.0 and net displays confidently while possibly
    // being materially wrong. The threshold exists precisely to prevent that.
    //
    // Below MIN_RATE_CANDIDATES the ratio is not measuring anything: with
    // fewer than 8 candidate legs a single missed pair swings the rate by 12.5
    // points or more, which is wider than the gap between the 80% and 50%
    // tiers. So we return an UNKNOWN rate (null) rather than a number, and
    // every consumer treats unknown the same way it treats sub-50%: show the
    // raw in and out figures, no net, and say why.
    var MIN_RATE_CANDIDATES = 8;
    var rate = candidates < MIN_RATE_CANDIDATES ? null : (detected / candidates);

    return { candidates: candidates, detected: detected, rate: rate };
}

async function handleGetFinanceNewSummary(request, env) {
    try {
        var user = await authenticate(request, env);
        if (!user) { return jsonErr("Unauthorized", 401); }
        if (user.role !== "alice" && user.role !== "rafa" && user.role !== "developer") { return jsonErr("Forbidden", 403); }

        var url = new URL(request.url);
        var month = url.searchParams.get("month");   // YYYY-MM
        var start, end;
        if (month && /^\d{4}-\d{2}$/.test(month)) {
            start = month + "-01";
        } else {
            var now = new Date();
            start = now.toISOString().slice(0, 7) + "-01";
        }
        end = start;   // computed in SQL via date(start,'+1 month')

        var detection = await computeTransferDetectionRate(env, start);

        // Confirmed transfers are always excluded. Suspected ones are excluded
        // too -- a suspected pair is far more likely to be a real transfer than
        // real income, and leaving it in double-counts both sides. The honesty
        // threshold below is what tells her how much to trust the result.
        var res = await env.DB.prepare(
            "SELECT a.purpose, " +
            "SUM(CASE WHEN t.amount_cents > 0 THEN t.amount_cents ELSE 0 END) AS in_cents, " +
            "SUM(CASE WHEN t.amount_cents < 0 THEN -t.amount_cents ELSE 0 END) AS out_cents, " +
            "SUM(CASE WHEN t.pending = 1 THEN ABS(t.amount_cents) ELSE 0 END) AS pending_cents, " +
            "COUNT(*) AS n " +
            "FROM transactions t JOIN accounts a ON a.id = t.account_id " +
            "WHERE t.date >= ? AND t.date < date(?, '+1 month') " +
            "AND t.transfer_status NOT IN ('suspected','confirmed') " +
            "GROUP BY a.purpose"
        ).bind(start, start).all();

        // rate === null means "not enough candidates to measure". It travels to
        // the client as null, never as a number, so the page can distinguish
        // "we measured badly" from "we could not measure at all".
        var rateKnown = detection.rate !== null;

        var out = {
            month: start.slice(0, 7),
            detection: {
                candidates: detection.candidates,
                detected:   detection.detected,
                rate:       rateKnown ? Math.round(detection.rate * 100) / 100 : null,
                known:      rateKnown
            }
        };

        // Unknown is not a low score, it is the absence of one -- and it lands
        // on the same side as a low score: no net.
        var netShown   = rateKnown && detection.rate >= 0.5;
        var netLabeled = rateKnown && detection.rate < 0.8;

        var purposes = ["business", "personal"];
        for (var p = 0; p < purposes.length; p++) {
            var row = null;
            for (var i = 0; i < res.results.length; i++) {
                if (res.results[i].purpose === purposes[p]) { row = res.results[i]; }
            }
            var inC  = row ? (row.in_cents  || 0) : 0;
            var outC = row ? (row.out_cents || 0) : 0;
            out[purposes[p]] = {
                in_cents:      inC,
                out_cents:     outC,
                net_cents:     inC - outC,
                pending_cents: row ? (row.pending_cents || 0) : 0,
                net_shown:     netShown,
                net_labeled:   netShown && netLabeled
            };
        }

        return jsonOk(out);
    } catch (e) {
        return jsonErr("Error building summary: " + e.message, 500);
    }
}

